/* Spanish translation of the Microsoft Certified: Security Operations Analyst Associate (SC-200) practice questions. Options keep the same order as the English bank. */
CertHub.addQuestionsEs("sc-200", {
  "sa1": ["Una herramienta administrativa legítima en un servidor sigue generando la misma alerta de Defender for Endpoint. El SOC quiere detener esa alerta solo para ese archivo en ese servidor y mantener toda la demás protección. ¿Qué deben crear?", ["Un indicador de permitir para el hash del archivo en todo el tenant", "Un grupo de dispositivos con la automatización configurada en sin respuesta", "Retirar (offboarding) el servidor de Defender for Endpoint", "Una regla de ajuste de alertas limitada a ese archivo y ese dispositivo"], "Las reglas de ajuste de alertas (supresión) ocultan o resuelven automáticamente un patrón específico de alerta benigna y dejan el sensor funcionando. Un indicador de permitir es tentador, pero cambia la prevención para todos los dispositivos del tenant, no solo las alertas de un servidor.", ["Un indicador de permitir cambia la prevención para ese hash en todos los dispositivos del tenant, lo cual es mucho más amplio que silenciar una alerta en un servidor.", "Un grupo de dispositivos sin respuesta automatizada solo cambia cómo las investigaciones automatizadas remedian; la alerta seguiría disparándose.", "El offboarding elimina toda la protección y visibilidad de Defender for Endpoint del servidor, lo que incumple el requisito de mantener la demás protección.", null]],
  "sa2": ["El gerente del SOC quiere recibir un correo cada vez que Defender XDR cree un incidente de severidad alta. ¿Qué se debe configurar?", ["El rol Security Operator para la cuenta del gerente", "Una regla de notificación de incidentes filtrada por severidad alta", "Un watchlist de Sentinel que contenga el correo del gerente", "La configuración del registro de auditoría unificado en Microsoft Purview"], "Las reglas de notificación de incidentes, en la configuración del portal de Defender, envían correos a los destinatarios elegidos para los incidentes que cumplen filtros como la severidad. Un rol solo otorga acceso al portal; no envía correos.", ["El rol Security Operator solo otorga permisos en el portal; los roles nunca envían notificaciones por correo.", null, "Un watchlist son datos de referencia que se consultan con KQL dentro de Sentinel; guardar ahí un correo no envía nada.", "El registro de auditoría unificado guarda la actividad de usuarios y administradores para búsquedas; no es un mecanismo de notificación de incidentes."]],
  "sa3": ["Antes de aplicar la regla de reducción de la superficie de ataque (ASR) que bloquea el robo de credenciales desde LSASS, el equipo de endpoints quiere ver qué aplicaciones se verían afectadas. ¿Qué deben hacer PRIMERO?", ["Implementar la regla en modo auditoría y revisar los eventos que registra", "Implementar la regla en modo bloqueo en los controladores de dominio", "Activar en su lugar el acceso controlado a carpetas en modo bloqueo", "Crear una regla de detección personalizada que copie la lógica ASR de la regla"], "El modo auditoría registra lo que la regla ASR habría bloqueado sin romper nada, para que puedas agregar exclusiones antes de aplicarla. Aplicar primero el modo bloqueo en servidores críticos es justamente la opción riesgosa que se busca evitar.", [null, "El modo bloqueo aplica la regla de inmediato y podría romper aplicaciones legítimas en servidores críticos, que es justo lo que el equipo quiere averiguar primero.", "El acceso controlado a carpetas protege las carpetas contra escrituras de ransomware; es otra función y no dice nada sobre el impacto de la regla de LSASS.", "Una detección personalizada solo genera alertas a partir de datos de hunting y no puede reproducir ni previsualizar el comportamiento de bloqueo del motor ASR."]],
  "sa4": ["Un atacante con derechos de administrador local intenta desactivar la protección en tiempo real de Microsoft Defender Antivirus mediante el registro. ¿Qué función impide este cambio?", ["Protección de red", "Acceso controlado a carpetas", "Protección contra alteraciones (tamper protection)", "Detección de dispositivos"], "La protección contra alteraciones bloquea configuraciones de seguridad como la protección en tiempo real para que no se puedan cambiar localmente, ni siquiera por administradores. La protección de red bloquea conexiones a dominios maliciosos; no protege configuraciones.", ["La protección de red bloquea conexiones salientes a dominios e IP maliciosos; no bloquea la configuración del antivirus.", "El acceso controlado a carpetas impide que aplicaciones no confiables escriban en carpetas protegidas, no cambios en la configuración de Defender.", null, "La detección de dispositivos encuentra dispositivos no administrados en la red; no tiene ningún papel en la protección de configuraciones de seguridad."]],
  "sa5": ["Los analistas de Tier 1 de la oficina de la UE deben ver y actuar solo sobre los endpoints de la UE en Defender for Endpoint. ¿Qué debe hacer el administrador?", ["Crear un grupo de dispositivos de la UE y dar acceso a él solo al grupo de los analistas", "Etiquetar los dispositivos de la UE y darles a los analistas el rol Security Reader en Entra", "Crear un workspace de Log Analytics separado para los dispositivos de la UE", "Agregar una política de Conditional Access que bloquee las páginas que no sean de la UE"], "Con el RBAC de Defender XDR, los grupos de dispositivos limitan qué dispositivos puede ver y administrar un grupo de usuarios. Un rol de Entra como Security Reader aplica a todo el tenant, así que las etiquetas por sí solas no lo restringen.", [null, "Security Reader es un rol de Entra para todo el tenant, así que las etiquetas no limitarían a los analistas a los dispositivos de la UE, y Reader no puede ejecutar acciones de respuesta.", "Los datos de Defender for Endpoint no se delimitan por workspaces de Log Analytics; un workspace separado no restringiría el portal de Defender.", "Conditional Access controla las condiciones de inicio de sesión en aplicaciones, no qué dispositivos puede ver un usuario dentro del portal de Defender."]],
  "sa6": ["Una empresa ejecuta cargas de trabajo en VM de Azure y en AWS EC2 y quiere la detección de amenazas para servidores de Defender for Cloud en ambas. ¿Qué se debe hacer?", ["Instalar el sensor de Defender for Identity en cada instancia EC2", "Conectar la cuenta de AWS a Defender for Cloud y habilitar Defender for Servers", "Confiar en el CSPM fundamental, que agrega alertas de amenazas para servidores", "Reenviar el syslog de EC2 a Sentinel mediante el conector Syslog"], "Defender for Cloud usa un conector multinube para AWS, y el plan Defender for Servers agrega protección contra amenazas para las cargas de trabajo, incluido Defender for Endpoint. El CSPM fundamental solo da recomendaciones de postura y secure score, no alertas de amenazas.", ["El sensor de Defender for Identity es para controladores de dominio y servidores de identidad como AD FS y AD CS, no para proteger cargas de trabajo en EC2.", null, "El CSPM fundamental da gratis recomendaciones de postura y secure score solamente; no agrega detección de amenazas para servidores.", "Reenviar syslog a Sentinel da registros en bruto para tus propias reglas, pero no habilita la protección contra amenazas para servidores de Defender for Cloud."]],
  "sa7": ["¿Qué capacidad de Defender for Cloud ofrece el secure score y recomendaciones básicas de seguridad sin costo adicional?", ["Defender CSPM", "Defender for Servers Plan 2", "CSPM fundamental (Foundational CSPM)", "Defender for Storage"], "El CSPM fundamental está activado por defecto y es gratuito. Defender CSPM agrega funciones de pago como el análisis de rutas de ataque, y los planes Defender for son protecciones de cargas de trabajo de pago.", ["Defender CSPM es el plan de postura de pago que agrega funciones como el análisis de rutas de ataque y el cloud security explorer.", "Defender for Servers Plan 2 es un plan de pago de protección de cargas de trabajo para máquinas, no la base gratuita de secure score.", null, "Defender for Storage es un plan de pago que detecta amenazas contra cuentas de almacenamiento, no la base gratuita de postura."]],
  "sa8": ["Un analista debe poder asignar, comentar y cerrar incidentes de Sentinel, pero no debe crear ni editar reglas de análisis. ¿Qué rol integrado es el adecuado?", ["Microsoft Sentinel Reader", "Microsoft Sentinel Contributor", "Log Analytics Reader", "Microsoft Sentinel Responder"], "Responder puede administrar incidentes (asignar, cambiar estado, cerrar) pero no puede crear ni modificar contenido. Contributor también puede editar reglas, lo cual es más de lo necesario, y Reader no puede modificar incidentes.", ["Sentinel Reader puede ver incidentes y contenido, pero no puede asignar, modificar ni cerrar incidentes.", "Sentinel Contributor también puede crear y editar reglas de análisis y otro contenido, lo que excede lo que este analista debe tener.", "Log Analytics Reader solo permite leer datos del workspace y no da derechos para administrar incidentes de Sentinel.", null]],
  "sa9": ["Una regla de automatización debe ejecutar un playbook, pero el grupo de recursos del playbook aparece deshabilitado (en gris) al elegirlo. ¿Cuál es la solución MÁS probable?", ["Mover el playbook dentro del propio workspace de Log Analytics", "Otorgar a Sentinel el rol Automation Contributor sobre ese grupo de recursos", "Darle al analista el rol Logic App Contributor en toda la suscripción", "Volver a crear el playbook con un desencadenador de alerta en lugar de incidente"], "Sentinel necesita permiso explícito (Microsoft Sentinel Automation Contributor) sobre el grupo de recursos del playbook antes de que las reglas de automatización puedan ejecutar playbooks ahí. Los derechos de Logic App del propio analista no le dan ese permiso a la cuenta de servicio de Sentinel.", ["Los playbooks son Logic Apps que viven en un grupo de recursos; no se pueden mover dentro de un workspace de Log Analytics.", null, "Los derechos de Logic App del propio analista no le dan a la cuenta de servicio de Sentinel permiso para ejecutar playbooks en ese grupo de recursos.", "El tipo de desencadenador afecta qué playbooks se pueden ejecutar, pero el grupo de recursos en gris es un problema de permisos, no del desencadenador."]],
  "sa10": ["Un firewall envía registros en Common Event Format. ¿Cómo deben llegar hoy a Sentinel?", ["A través de un reenviador Linux usando el conector CEF via AMA y una DCR", "A través del agente heredado de Log Analytics instalado directamente en el firewall", "A través del conector Windows Security Events via AMA", "Directamente del firewall al workspace sin reenviador"], "Los dispositivos que no pueden ejecutar un agente envían CEF por syslog a un reenviador Linux que ejecuta el Azure Monitor Agent, y una regla de recopilación de datos (DCR) envía los eventos a la tabla CommonSecurityLog. El agente heredado de Log Analytics (MMA) está retirado.", [null, "El agente heredado de Log Analytics (MMA) está retirado y, en general, los firewalls no pueden ejecutar ningún agente.", "Windows Security Events via AMA recopila registros de eventos de Windows desde máquinas Windows, no CEF por syslog desde dispositivos.", "Los firewalls no pueden escribir directamente en un workspace de Log Analytics; CEF necesita un reenviador con el Azure Monitor Agent y una DCR."]],
  "sa11": ["Los costos de ingesta de los controladores de dominio son demasiado altos. El SOC solo necesita un pequeño conjunto de IDs de eventos de Windows específicos. ¿Cuál es el MEJOR enfoque?", ["El conjunto All Security Events y luego filtrar dentro de las reglas de análisis", "Un watchlist con los IDs de evento necesarios vinculado al conector", "Una regla de recopilación de datos con un filtro XPath personalizado para esos IDs de evento", "Reducir la retención del workspace a 30 días para compensar la ingesta"], "Las DCR filtran los eventos en el origen, así que solo pagas por lo que recopilas. Filtrar dentro de las reglas de análisis igual ingiere y factura cada evento, y reducir la retención no baja los cargos de ingesta.", ["Recopilar All Security Events ingiere y factura cada evento; filtrar después en las reglas no reduce el costo de ingesta.", "Los watchlists son datos de referencia para consultas y no se pueden vincular a un conector para filtrar lo que se recopila.", null, "La retención se factura aparte de la ingesta, así que acortarla no reduce los cargos de ingesta, que son el problema."]],
  "sa12": ["Un equipo quiere instalar juntos el conector de datos, las reglas de análisis, los workbooks y las consultas de hunting de un producto de terceros. ¿A dónde deben ir?", ["Solo a la pestaña Community del repositorio de GitHub de Sentinel", "A la página de plantillas de reglas de análisis, una plantilla a la vez", "A la página Data connectors del portal de Azure Monitor", "A la solución del producto en el Content hub de Sentinel"], "Las soluciones del Content hub empaquetan conectores, reglas, workbooks, parsers y consultas de hunting para que se instalen y actualicen como una sola unidad. Agregar plantillas una por una omite el conector y el workbook.", ["El repositorio de GitHub aloja contenido de la comunidad, pero instalarlo manualmente no da una solución empaquetada y actualizable con su conector.", "Agregar plantillas de reglas una por una omite el conector, los workbooks y las consultas de hunting que vienen con el producto.", "Las páginas propias de Azure Monitor administran agentes y DCR; no instalan paquetes de contenido de Sentinel.", null]],
  "sa13": ["Los desarrolladores quieren que una aplicación interna envíe eventos de seguridad en JSON a una tabla personalizada de Sentinel por HTTPS. ¿Qué método deben usar?", ["La HTTP Data Collector API con una clave compartida del workspace", "La Logs Ingestion API con una regla de recopilación de datos y una tabla personalizada", "Un conector Syslog via AMA en el servidor de la aplicación", "Windows Event Forwarding hacia un servidor recolector"], "La Logs Ingestion API envía los datos a través de una DCR, que puede transformarlos, hacia una tabla personalizada usando autenticación de Entra ID. La antigua HTTP Data Collector API se está retirando y depende de una clave compartida.", ["La HTTP Data Collector API es el método heredado que usa una clave compartida del workspace y se está retirando.", null, "Syslog via AMA recopila mensajes syslog de hosts Linux; no es una API HTTPS para que una aplicación publique JSON.", "Windows Event Forwarding mueve registros de eventos de Windows entre servidores y no acepta JSON personalizado de una aplicación."]],
  "sa14": ["¿Por qué una regla de análisis programada debe mapear entidades como Account, Host e IP?", ["Para que la consulta se ejecute más rápido contra el nivel de análisis", "Para que la regla pueda ejecutarse como regla casi en tiempo real", "Para que las alertas lleven entidades estructuradas para pivotar, agrupar y para UEBA", "Para que Sentinel pueda omitir la ingesta de columnas no mapeadas"], "El mapeo de entidades convierte columnas de la consulta en entidades que alimentan el gráfico de investigación, las páginas de entidades, la agrupación de alertas y la correlación. No cambia la velocidad de la consulta ni lo que se ingiere.", ["El mapeo de entidades ocurre después de que la consulta devuelve resultados; no hace que la consulta sea más rápida.", "NRT es un tipo de regla distinto que se elige al crearla; el mapeo de entidades no cambia el tipo de regla.", null, "El mapeo de entidades no afecta la ingesta; todas las columnas de la tabla se siguen almacenando, estén mapeadas o no."]],
  "sa15": ["Una detección de la adición de un usuario a Domain Admins debe generar una alerta en aproximadamente un minuto desde que llega el evento. ¿Qué tipo de regla es el MEJOR?", ["Una regla de análisis casi en tiempo real (NRT)", "Una regla programada configurada para ejecutarse cada cinco minutos", "Una regla de anomalías basada en machine learning", "Una regla Fusion de ataques de varias etapas"], "Las reglas NRT se ejecutan aproximadamente una vez por minuto sobre los datos recién llegados, lo que es ideal para eventos simples y de alto valor. Las reglas programadas no pueden ejecutarse más de una vez cada cinco minutos, y las reglas de anomalías y Fusion no están hechas para un evento único específico.", [null, "Las reglas programadas se ejecutan como máximo cada cinco minutos y suelen sumar retraso de ingesta, así que no pueden alertar de forma confiable en un minuto.", "Las reglas de anomalías usan líneas base de machine learning a lo largo del tiempo y no están diseñadas para dispararse con un solo evento específico.", "Fusion correlaciona varias alertas en incidentes de varias etapas; no es una regla que escribes para detectar rápido un evento específico."]],
  "sa16": ["Una regla de fuerza bruta crea cientos de incidentes al día, uno por cada alerta sobre el mismo usuario. ¿Qué reduce esto sin perder alertas?", ["Un umbral más alto en la regla, para que la mayoría de las alertas ya no se disparen", "Una regla de automatización que cierre cada incidente nuevo", "Cambiar de una regla programada a una regla NRT", "Agrupar alertas por entidades coincidentes dentro de una ventana de tiempo"], "La agrupación de alertas agrega las alertas relacionadas (por ejemplo, la misma cuenta dentro de 24 horas) a un solo incidente, así que no se pierde nada. Subir el umbral o cerrar incidentes automáticamente oculta detecciones reales.", ["Subir el umbral suprime detecciones reales en lugar de consolidarlas, así que se pierden alertas.", "Cerrar automáticamente cada incidente oculta ataques reales y anula el propósito de la regla.", "Cambiar a NRT modifica la frecuencia de ejecución de la regla, pero no agrupa las alertas relacionadas en un solo incidente.", null]],
  "sa17": ["Tras activar el conector de Microsoft Defender XDR con integración de incidentes en Sentinel, el equipo ve incidentes duplicados para las mismas alertas de Defender. ¿Qué deben hacer?", ["Eliminar el conector de Defender XDR y usar los conectores antiguos de cada producto", "Desactivar las reglas de creación de incidentes de Microsoft para los productos de Defender", "Agregar una regla de automatización que cierre los incidentes que provienen de Defender", "Bajar la severidad de todas las alertas de Defender en Sentinel"], "Con la integración de incidentes, los incidentes de Defender XDR se sincronizan en Sentinel. Las reglas de creación de incidentes de Microsoft para los mismos productos crean una segunda copia, por lo que deben desactivarse (el conector ofrece hacerlo).", ["El conector de Defender XDR con integración de incidentes es el enfoque recomendado; volver a los conectores antiguos pierde la correlación y la sincronización.", null, "Cerrar automáticamente los incidentes de Defender también oculta las copias sincronizadas y trata el síntoma en lugar de eliminar la fuente del duplicado.", "Cambiar la severidad no impide que se creen dos incidentes para las mismas alertas."]],
  "sa18": ["¿Qué columnas debe devolver una consulta de advanced hunting de Defender XDR antes de poder guardarla como regla de detección personalizada?", ["Solo Timestamp y un valor de Severity calculado en la consulta", "Una columna llamada AlertTitle y otra llamada MitreTechnique", "Timestamp, un ID de evento como ReportId y una columna de entidad como DeviceId", "Cualquier columna, siempre que la consulta use summarize"], "Las detecciones personalizadas necesitan la hora del evento, una columna que identifique el registro del evento y al menos una columna de entidad afectada para que las alertas se vinculen a dispositivos, usuarios o buzones. La severidad y las técnicas de MITRE se configuran en el asistente de la regla, no en columnas de la consulta.", ["La severidad se elige en el asistente de la regla, y Timestamp por sí solo no basta; la consulta también necesita un ID de registro y una columna de entidad.", "AlertTitle y las técnicas de MITRE se ingresan en los detalles de la alerta del asistente, no se devuelven como columnas de la consulta.", null, "summarize no es obligatorio, y una consulta que al resumir elimina las columnas requeridas no se puede guardar como detección."]],
  "sa19": ["Los incidentes de una regla de análisis específica deben asignarse a la cola de Tier 2 y su severidad debe subir automáticamente. ¿Cuál es la solución más sencilla?", ["Una regla de automatización que se ejecute al crearse el incidente", "Un playbook con desencadenador de alerta que llame a la Graph API", "Un cambio en el KQL de la regla que agregue una columna Owner", "Un workbook que resalte los incidentes de esa regla"], "Las reglas de automatización pueden establecer el propietario, la severidad, el estado, las etiquetas y las tareas sin código. Un playbook también podría hacerlo, pero agrega costo y complejidad para algo que ya viene integrado.", [null, "Un playbook podría hacerlo, pero agrega una Logic App, costo y código para algo que las reglas de automatización hacen de forma nativa.", "Agregar una columna Owner a la salida de la consulta no asigna el incidente a nadie en Sentinel.", "Un workbook solo visualiza datos; no puede cambiar el propietario ni la severidad de un incidente."]],
  "sa20": ["Cuando se crea un incidente nuevo, el SOC quiere consultar cada IP en un servicio de reputación y publicar los resultados en un canal de Teams. ¿Qué se debe construir?", ["Solo una regla de automatización, usando una condición integrada 'post message'", "Un watchlist actualizado desde el servicio de reputación", "Una regla de análisis programada que consulte el sitio de reputación", "Un playbook ejecutado por una regla de automatización cuando se crea un incidente"], "Llamar a API externas y publicar en Teams requiere conectores de Logic Apps, que es lo que ofrecen los playbooks. La regla de automatización es el desencadenador que ejecuta el playbook.", ["Las reglas de automatización no tienen una acción integrada para llamar a API externas ni publicar en Teams; para eso solo pueden ejecutar un playbook.", "Un watchlist almacena datos de referencia y no puede publicar resultados de enriquecimiento en Teams cuando se crea un incidente.", "Una regla de análisis consulta datos del workspace; no puede llamar a un sitio web externo de reputación ni publicar mensajes.", null]],
  "sa21": ["Los analistas necesitan una lista de cuentas VIP que varias reglas de análisis puedan referenciar y que RR. HH. pueda actualizar desde un CSV. ¿Qué se debe usar?", ["Una tabla personalizada llenada mediante la Logs Ingestion API", "Una lista dynamic() fija dentro de cada regla", "Un watchlist de Sentinel consultado con _GetWatchlist()", "Una etiqueta de dispositivo de Defender XDR llamada VIP"], "Los watchlists contienen datos de referencia, se actualizan fácilmente desde un CSV y se leen en KQL con _GetWatchlist. Fijar la lista en cada regla implica editar todas las reglas cada vez que cambia.", ["Una tabla personalizada vía la Logs Ingestion API es más pesada de construir y mantener, y RR. HH. no podría simplemente subir un CSV para actualizarla.", "Fijar una lista dynamic() en cada regla implica editar todas las reglas cada vez que cambia la lista de VIP.", null, "Las etiquetas de dispositivo marcan dispositivos en Defender XDR; no pueden contener una lista de cuentas de usuario para que la usen las reglas de Sentinel."]],
  "sa22": ["El líder del SOC quiere ver qué técnicas de MITRE ATT&CK cubren las reglas de análisis activas y cuáles no tienen cobertura. ¿Dónde debe buscar?", ["La página Threat analytics en Defender XDR", "La página MITRE ATT&CK en Microsoft Sentinel", "La página Secure score en Defender for Cloud", "El Content hub filtrado por proveedor"], "La vista MITRE ATT&CK de Sentinel muestra la cobertura por reglas activas y disponibles para cada técnica. Threat analytics cubre campañas de amenazas, no la cobertura de tus reglas.", ["Threat analytics cubre los informes de Microsoft sobre campañas de amenazas y tu exposición, no qué técnicas cubren tus propias reglas.", null, "El secure score de Defender for Cloud mide la postura de configuración, no la cobertura de detección de MITRE ATT&CK.", "Filtrar el Content hub por proveedor muestra soluciones instalables, no un mapa de cobertura de tus reglas activas por técnica."]],
  "sa23": ["¿Qué función de Sentinel recomienda acciones como recortar la ingesta de datos que ninguna regla usa o agregar detecciones para brechas frente a escenarios de ataque comunes?", ["UEBA", "Workbooks", "Livestream", "SOC optimization"], "SOC optimization analiza tu ingesta y tus detecciones y sugiere mejoras de costo y cobertura. Los workbooks solo muestran los datos que consultes.", ["UEBA construye líneas base de comportamiento para usuarios y entidades; no recomienda cambios de ingesta ni de detección.", "Los workbooks muestran las consultas que construyas; no analizan tu SOC ni sugieren mejoras.", "Livestream ejecuta una consulta de hunting de forma continua sobre datos nuevos; no hace recomendaciones de costo ni de cobertura.", null]],
  "sa24": ["Registros de flujo de red de alto volumen deben conservarse un año para investigaciones ocasionales, pero ninguna regla de análisis los necesita. ¿Cuál es la opción MÁS rentable?", ["Almacenarlos en el nivel data lake de Sentinel y consultarlos cuando se necesite", "Mantenerlos en el nivel de análisis con un año de retención interactiva", "Cargarlos en un watchlist para que los analistas puedan buscarlos", "Ingerirlos a diario y luego eliminarlos después de 30 días"], "El nivel data lake está pensado para almacenar a bajo costo y a largo plazo datos de alto volumen que se consultan de vez en cuando. El nivel de análisis es la opción cara en este caso, ya que ninguna detección necesita los datos.", [null, "Un año de retención interactiva en el nivel de análisis para registros de alto volumen es la opción más cara, y ninguna detección necesita esa velocidad.", "Los watchlists son listas de referencia pequeñas con límites de tamaño, no un almacén para registros de flujo de alto volumen.", "Eliminar los registros después de 30 días incumple el requisito de conservarlos un año."]],
  "sa25": ["¿Qué función de Sentinel construye paneles interactivos de volumen de ingesta, tendencias de incidentes y métricas del SOC a partir de consultas KQL?", ["Workbooks", "Watchlists", "Notebooks", "Reglas de automatización"], "Los workbooks son paneles de Azure Monitor impulsados por KQL. Los notebooks son entornos Jupyter para análisis más profundos, no paneles.", [null, "Los watchlists contienen datos de referencia, como listas de VIP; no generan paneles.", "Los notebooks son entornos Jupyter para análisis profundos con Python, no paneles KQL interactivos para métricas del SOC.", "Las reglas de automatización actúan sobre incidentes (asignar, etiquetar, ejecutar playbooks); no producen visualizaciones."]],
  "sa26": ["El equipo de datos quiere alertas de intentos de inyección SQL contra una base de datos Azure SQL. ¿Qué plan se debe activar?", ["Defender for Storage", "Defender for Databases (Defender for Azure SQL)", "Defender CSPM", "Defender for App Service"], "El plan de bases de datos detecta amenazas como la inyección SQL y accesos inusuales a Azure SQL. Defender for Storage vigila cuentas de almacenamiento, no consultas SQL.", ["Defender for Storage detecta amenazas contra cuentas de almacenamiento, como la carga de malware, no la inyección SQL.", null, "Defender CSPM agrega funciones de postura como el análisis de rutas de ataque; no genera alertas de amenazas de inyección SQL.", "Defender for App Service protege aplicaciones web alojadas en App Service, no la base de datos Azure SQL en sí."]],
  "sa27": ["¿Dónde se debe instalar el sensor de Defender for Identity para supervisar la autenticación de Active Directory local?", ["En cada estación de trabajo miembro del dominio", "Solo en el servidor de Microsoft Entra Connect, no en los DC", "En los controladores de dominio y en los servidores AD FS o AD CS", "En un reenviador syslog Linux en la DMZ"], "El sensor lee el tráfico y los eventos de autenticación directamente en los controladores de dominio (y en servidores de identidad como AD FS y AD CS). Ponerlo solo en el servidor de Entra Connect deja fuera el tráfico de los DC.", ["Las estaciones de trabajo las cubre Defender for Endpoint; el sensor de Defender for Identity va en la infraestructura de identidad.", "El servidor de Entra Connect puede tener un sensor, pero instalarlo solo ahí deja fuera el tráfico de autenticación de los controladores de dominio.", null, "El sensor se ejecuta en servidores de identidad Windows y lee el tráfico localmente; un reenviador syslog Linux no es una ubicación compatible."]],
  "sa28": ["A veces los usuarios hacen clic en enlaces de correos que eran seguros al entregarse, pero que luego empiezan a alojar una página de phishing. ¿Qué función de Defender for Office 365 los protege?", ["Entrega dinámica de Safe Attachments", "Zero-hour auto purge solo para malware", "Política antispam de salida", "Verificación de URL en el momento del clic de Safe Links"], "Safe Links reescribe las URL y las vuelve a verificar cuando el usuario hace clic, así que detecta enlaces que se vuelven maliciosos después de la entrega. Safe Attachments detona adjuntos, no enlaces.", ["Safe Attachments detona los adjuntos en un sandbox; la entrega dinámica maneja adjuntos, no los enlaces del cuerpo del mensaje.", "Zero-hour auto purge puede eliminar mensajes después de la entrega, pero limitarlo a malware no protege a un usuario que hace clic en un enlace que se volvió malicioso.", "Las políticas antispam de salida controlan el correo que envían tus usuarios, no los enlaces entrantes en los que hacen clic.", null]],
  "sa29": ["¿Cuál es la forma más fácil de incorporar cientos de VM Windows y Linux de Azure a Defender for Endpoint?", ["Ejecutar a mano el script de incorporación local en cada VM", "Instalar el sensor de Defender for Identity en cada VM", "Habilitar Defender for Servers, que implementa la integración con Defender for Endpoint", "Conectar las VM mediante el conector Windows Security Events"], "Defender for Servers incluye Defender for Endpoint y puede implementar el sensor automáticamente en las máquinas compatibles. Los scripts locales funcionan, pero no escalan.", ["Ejecutar el script local en cada VM funciona, pero no escala a cientos de máquinas y es propenso a errores.", "El sensor de Defender for Identity supervisa Active Directory en los DC; no incorpora VM a Defender for Endpoint.", null, "El conector Windows Security Events envía registros de eventos a Sentinel; no incorpora máquinas a Defender for Endpoint e ignora Linux."]],
  "sa30": ["El SOC sospecha que hay laptops no administradas y dispositivos IoT en la red corporativa. ¿Qué función de Defender for Endpoint puede encontrarlos usando los dispositivos incorporados?", ["Protección contra alteraciones", "Live response", "Reducción de la superficie de ataque", "Detección de dispositivos (device discovery)"], "La detección de dispositivos usa los endpoints incorporados para encontrar dispositivos no administrados en las mismas redes, para poder incorporarlos o evaluarlos. Live response es un shell remoto en dispositivos que ya administras.", ["La protección contra alteraciones bloquea la configuración de Defender en dispositivos administrados; no encuentra los no administrados.", "Live response es un shell remoto en dispositivos que ya están incorporados, no una herramienta de detección.", "Las reglas de reducción de la superficie de ataque bloquean comportamientos riesgosos en endpoints administrados y no hacen inventario de dispositivos desconocidos.", null]],
  "sa31": ["El SOC quiere impedir que todos los endpoints lleguen a un dominio de comando y control conocido. ¿Qué debe estar implementado para que funcione un indicador de dominio con acción Block?", ["La protección contra alteraciones desactivada", "La protección de red activada en modo bloqueo", "El acceso controlado a carpetas activado en modo auditoría", "Un conector de datos de TI de Sentinel"], "Los indicadores de URL y dominio se aplican mediante la protección de red (y SmartScreen en Edge). Sin la protección de red, los demás navegadores y procesos no se bloquean.", ["Desactivar la protección contra alteraciones debilita la seguridad y no tiene nada que ver con aplicar indicadores de dominio.", null, "El acceso controlado a carpetas protege carpetas contra escrituras no confiables; además, el modo auditoría no bloquearía nada.", "Un conector de TI de Sentinel trae indicadores a Sentinel para correlacionarlos, pero no aplica el bloqueo en los endpoints."]],
  "sa32": ["Los analistas quieren trabajar los incidentes de Sentinel y de Defender XDR en una sola cola en el portal de Defender. ¿Qué se requiere?", ["Incorporar el workspace de Sentinel al portal de Defender", "Exportar los incidentes de Sentinel a un watchlist de Defender", "Asignar a cada analista el rol Global Administrator", "Construir una Logic App que copie incidentes entre portales"], "Conectar el workspace al portal de Defender (la plataforma unificada de operaciones de seguridad) pone los incidentes de Sentinel y Defender XDR en una sola cola con hunting compartido. Global Administrator es demasiado amplio y no conecta nada.", [null, "Los watchlists contienen datos de referencia; exportar incidentes a uno no crea una cola de incidentes compartida.", "Global Administrator es un privilegio excesivo y no conecta Sentinel con el portal de Defender.", "Una Logic App personalizada que copie incidentes es frágil e innecesaria cuando el workspace se puede incorporar a la plataforma unificada."]],
  "sa33": ["Los analistas quieren que los inicios de sesión de cada usuario se comparen con su comportamiento normal y con el de sus pares, y que se muestren como insights en las páginas de entidades. ¿Qué se debe activar?", ["La regla Fusion con todas las fuentes de alertas", "User and Entity Behavior Analytics (UEBA) con sus fuentes de datos", "Un workbook construido sobre la tabla SigninLogs", "Políticas de sesión de Defender for Cloud Apps"], "UEBA construye líneas base a partir de fuentes como los registros de inicio de sesión y auditoría, y agrega anomalías y comparaciones con pares a las páginas de entidades. Fusion correlaciona alertas; no construye líneas base por usuario.", ["Fusion correlaciona alertas en incidentes de varias etapas; no construye líneas base por usuario ni comparaciones con pares.", null, "Un workbook sobre SigninLogs puede graficar inicios de sesión, pero no calcula líneas base de comportamiento ni agrega insights a las páginas de entidades.", "Las políticas de sesión de Defender for Cloud Apps controlan sesiones en vivo hacia aplicaciones; no agregan insights de UEBA en Sentinel."]],
  "sa34": ["Un socio comparte indicadores de amenazas mediante un servidor STIX/TAXII 2.x. ¿Cómo debe ingerirlos Sentinel?", ["El conector Syslog via AMA", "Una carga semanal de un CSV en un watchlist de Sentinel", "El conector de Defender for Cloud Apps", "El conector de datos Threat Intelligence TAXII"], "El conector TAXII consulta periódicamente las fuentes STIX y almacena los indicadores como objetos de inteligencia de amenazas que las reglas y el hunting pueden correlacionar. Una carga semanal a un watchlist se desactualiza y pierde los detalles STIX.", ["Syslog via AMA recopila mensajes syslog de hosts Linux; no puede consultar un servidor STIX/TAXII.", "Una carga semanal de CSV a un watchlist es manual, se desactualiza y descarta los detalles de los objetos STIX.", "El conector de Defender for Cloud Apps trae alertas y registros de aplicaciones en la nube, no fuentes de inteligencia de amenazas de socios.", null]],
  "sa35": ["Registros de proxy muy detallados están en un nivel de bajo costo. El SOC quiere un agregado por hora de bytes por usuario en el nivel de análisis para paneles y detecciones. ¿Qué deben crear?", ["Una regla casi en tiempo real sobre el nivel de bajo costo", "Un watchlist actualizado cada hora", "Una regla de resumen (summary rule) que escriba los resultados agregados en una tabla de análisis", "Un workbook con actualización automática activada"], "Las summary rules ejecutan una agregación KQL según un horario y guardan el resultado, más pequeño, en una tabla del nivel de análisis, lo que reduce el costo y mantiene la utilidad de los datos. Un workbook solo muestra datos; no almacena resultados para las reglas.", ["Las reglas NRT se ejecutan cada minuto sobre datos del nivel de análisis y no escriben resultados agregados en una tabla.", "Un watchlist son datos de referencia mantenidos manualmente, no una agregación programada de registros de proxy.", null, "La actualización automática solo vuelve a dibujar un panel; no almacena resultados que las reglas de análisis puedan consultar."]],
  "sa36": ["¿Qué tipo de regla de análisis de Sentinel correlaciona alertas y anomalías de baja fidelidad de varios productos en incidentes de ataques de varias etapas de alta fidelidad?", ["Fusion", "Casi en tiempo real (NRT)", "Creación de incidentes de Microsoft", "Anomalías"], "Fusion usa machine learning para correlacionar señales entre productos en incidentes de varias etapas y está activada por defecto. Las reglas de anomalías producen registros de anomalías por sí solas y son una de las entradas que Fusion puede usar.", [null, "Las reglas NRT ejecutan una sola consulta KQL aproximadamente cada minuto; no correlacionan alertas entre productos.", "Las reglas de creación de incidentes de Microsoft convierten las alertas de productos de Microsoft en incidentes uno a uno, sin correlación de varias etapas.", "Las reglas de anomalías producen registros de anomalías individuales; son una entrada que Fusion puede usar, no el motor de correlación en sí."]],
  "sa37": ["Los analistas quieren que la línea de comandos sospechosa aparezca en cada alerta de una regla programada para poder filtrar y hacer triage sin abrir los registros en bruto. ¿Qué debe configurar el autor de la regla?", ["Una entidad File mapeada al valor de la columna CommandLine", "Detalles personalizados (custom details) que expongan la columna CommandLine", "Un watchlist con las líneas de comandos vistas hasta ahora", "Agrupación de alertas que agrupe los incidentes por línea de comandos"], "Los detalles personalizados copian columnas elegidas de la consulta a la alerta para que aparezcan en la alerta y en el incidente. Una entidad File describe un archivo, no una línea de comandos, así que mapear la línea de comandos a ella es engañoso.", ["Una entidad File describe un archivo, y forzar una línea de comandos en ella produce entidades engañosas en lugar de un campo legible.", null, "Un watchlist de líneas de comandos pasadas no pone la línea de comandos de la alerta actual en la alerta.", "La agrupación de alertas controla cómo las alertas forman incidentes; no muestra la línea de comandos en cada alerta."]],
  "sa38": ["Un incidente de Defender XDR vincula alertas de correo, de una laptop y de una identidad. El analista quiere ver la secuencia de eventos y los activos en una sola página. ¿Dónde debe buscar?", ["El inventario de software del dispositivo", "La página Secure score", "La attack story del incidente", "La pestaña de historial del Action center"], "La attack story muestra las alertas correlacionadas en orden, con un gráfico del incidente de los activos afectados. El inventario de software lista los programas instalados, no la secuencia del ataque.", ["El inventario de software lista los programas instalados en un dispositivo, no la secuencia correlacionada de eventos entre activos.", "El secure score mide la postura de seguridad; no contiene una línea de tiempo del incidente.", null, "El historial del Action center muestra las acciones de remediación ejecutadas, no la secuencia completa del ataque y los activos afectados."]],
  "sa39": ["Una laptop está enviando beacons a un servidor de comando y control. El analista debe detener el movimiento lateral, pero seguir recopilando telemetría y ejecutando acciones de respuesta. ¿Qué acción es la adecuada?", ["Aislar el dispositivo", "Restringir la ejecución de aplicaciones", "Retirar (offboard) el dispositivo", "Ejecutar un análisis rápido de antivirus"], "El aislamiento bloquea todo el tráfico de red excepto la conexión con el servicio de Defender, así que la investigación y la respuesta pueden continuar. El offboarding eliminaría tu visibilidad.", [null, "Restringir la ejecución de aplicaciones bloquea código no firmado, pero deja la conectividad de red activa, así que el movimiento lateral por la red sigue siendo posible.", "El offboarding elimina el sensor, así que pierdes la telemetría y las acciones de respuesta que necesitas conservar.", "Un análisis de antivirus puede encontrar malware, pero no impide que el dispositivo se comunique con otros hosts."]],
  "sa40": ["El responsable de respuesta a incidentes necesita los autoruns, los procesos en ejecución, las conexiones de red y los registros de eventos de un dispositivo remoto en una sola descarga. ¿Qué acción debe usar?", ["Ejecutar análisis de antivirus", "Iniciar una investigación automatizada", "Restringir la ejecución de aplicaciones", "Recopilar paquete de investigación (Collect investigation package)"], "El paquete de investigación reúne datos forenses como procesos, servicios, tareas programadas, conexiones de red y registros en un archivo zip. Un análisis solo busca malware.", ["Un análisis de antivirus busca malware y devuelve detecciones, no un paquete forense de procesos, autoruns y registros.", "Una investigación automatizada analiza y remedia por sí sola; no le da al responsable un paquete forense descargable.", "Restringir la ejecución de aplicaciones limita qué código puede ejecutarse; no recopila datos.", null]],
  "sa41": ["Un analista necesita extraer una DLL sospechosa de un endpoint remoto para analizarla y listar sus tareas programadas. ¿Qué capacidad lo permite?", ["Una sesión de live response con comandos como getfile", "El botón 'Download file' de la página del archivo, que funciona en todos los casos", "Threat Explorer con el hash del archivo", "Una consulta de advanced hunting sobre DeviceFileEvents"], "Live response ofrece un shell remoto para recopilar archivos, ejecutar scripts aprobados y revisar el estado. Advanced hunting muestra eventos sobre el archivo, pero no puede recuperarlo.", [null, "Download file en la página del archivo depende de que el archivo se haya recopilado y no siempre está disponible; además, no puede listar tareas programadas.", "Threat Explorer es una herramienta de Defender for Office 365 para correo; no puede recuperar archivos de un endpoint.", "Advanced hunting muestra eventos sobre el archivo, pero no puede extraer el archivo ni ejecutar comandos en el dispositivo."]],
  "sa42": ["Un ejecutable malicioso se está ejecutando en varios dispositivos. El analista quiere terminar sus procesos y ponerlo en cuarentena dondequiera que se encuentre. ¿Qué acción debe tomar desde la página del archivo?", ["Agregar el archivo a una regla de ajuste de alertas", "Stop and quarantine file", "Recopilar el paquete de investigación en cada dispositivo", "Enviar el archivo solo a análisis profundo"], "Stop and quarantine file termina los procesos en ejecución y pone el archivo en cuarentena en los dispositivos donde se encuentre. El análisis profundo da información, pero no contiene nada.", ["El ajuste de alertas solo oculta o resuelve alertas; el malware seguiría ejecutándose.", null, "Recopilar paquetes de investigación reúne datos forenses, pero no termina procesos ni pone el archivo en cuarentena.", "El análisis profundo detona el archivo para generar un informe; no contiene nada en los dispositivos afectados."]],
  "sa43": ["La laptop de un usuario de finanzas ejecuta una herramienta de hacking no firmada, pero el usuario debe seguir trabajando con el correo y Teams durante la investigación. ¿Qué acción es la adecuada?", ["Aislar el dispositivo de la red", "Retirar el dispositivo y reinstalar la imagen de inmediato", "Desactivar la protección contra alteraciones para permitir la limpieza", "Restringir la ejecución de aplicaciones a código firmado por Microsoft"], "Restringir la ejecución de aplicaciones detiene el código no firmado mientras la red sigue activa, así que las aplicaciones firmadas por Microsoft siguen funcionando. El aislamiento dejaría al usuario completamente desconectado.", ["El aislamiento corta todo el tráfico de red excepto hacia Defender, así que el usuario no podría seguir usando el correo y Teams.", "Retirar y reinstalar la imagen de inmediato destruye evidencia y elimina la visibilidad antes de terminar la investigación.", "Desactivar la protección contra alteraciones debilita las defensas del dispositivo y no detiene la herramienta de hacking.", null]],
  "sa44": ["Un correo de phishing llegó a 300 buzones antes de ser detectado. ¿Cómo debe el analista eliminar las copias?", ["Pedir a cada usuario que elimine el correo y vacíe la papelera", "Bloquear al remitente y esperar a zero-hour auto purge", "Encontrar los mensajes en Threat Explorer y aplicar una acción de eliminación temporal (soft delete)", "Crear una regla de flujo de correo, que solo afecta a los mensajes enviados en el futuro"], "Threat Explorer (o advanced hunting) puede encontrar todas las copias entregadas y eliminarlas de una sola vez, con la acción registrada en el Action center. Bloquear al remitente solo afecta el correo futuro.", ["Depender de que 300 usuarios eliminen el correo es lento, poco confiable y deja copias.", "Bloquear al remitente solo afecta el correo futuro, y ZAP puede no actuar sobre mensajes que no reclasifique.", null, "Las reglas de flujo de correo actúan sobre mensajes en tránsito, así que no pueden eliminar copias ya entregadas a los buzones."]],
  "sa45": ["¿Dónde revisa un analista los correos que los usuarios marcaron con el botón Report integrado?", ["La pestaña User reported de la página Submissions", "La página Quarantine en Review", "La página de informes de Attack simulation training", "Los resultados de content search de Purview"], "Los mensajes reportados por usuarios aparecen en la página Submissions, donde los analistas pueden hacerles triage y enviarlos a Microsoft. Quarantine contiene los mensajes que atraparon los filtros, no los que reportaron los usuarios.", [null, "Quarantine contiene los mensajes que atraparon las políticas de filtrado, no los mensajes que los usuarios reportaron con el botón Report.", "Los informes de Attack simulation training cubren campañas de phishing simuladas, no mensajes reales reportados por usuarios.", "Content search de Purview encuentra contenido para eDiscovery; no es la cola de triage de mensajes reportados por usuarios."]],
  "sa46": ["Defender for Identity genera 'Suspected DCSync attack' desde una estación de trabajo. ¿Qué significa esta alerta?", ["El reloj de una estación de trabajo no está sincronizado con el controlador de dominio", "Un host que no es DC le pidió a un controlador de dominio replicar datos del directorio, como hashes de contraseñas", "Un usuario cambió su contraseña en un dispositivo unido al dominio", "Group Policy no se replicó entre controladores de dominio"], "DCSync abusa de los derechos de replicación para extraer material de credenciales. Solo los controladores de dominio deben replicar, así que una solicitud desde una estación de trabajo sugiere fuertemente robo de credenciales. No tiene nada que ver con la sincronización de hora.", ["DCSync no tiene nada que ver con la hora del reloj; abusa de la replicación del directorio para robar credenciales.", null, "Un cambio de contraseña normal es rutinario y no implica que una estación de trabajo solicite replicación a un DC.", "Las fallas de replicación entre DC son un problema operativo; DCSync es un equipo que no es DC haciéndose pasar por uno para extraer secretos."]],
  "sa47": ["El analista quiere ver cómo comprometer una estación de trabajo de la mesa de ayuda podría permitir a un atacante llegar a una cuenta Domain Admin mediante sesiones guardadas y derechos de administrador local. ¿Qué función de Defender for Identity lo muestra?", ["Alertas de honeytoken", "Etiquetas de entidad", "Rutas de movimiento lateral (lateral movement paths)", "Estado de los sensores"], "Las rutas de movimiento lateral muestran cómo los atacantes podrían saltar entre máquinas y credenciales para llegar a cuentas sensibles. Los honeytokens son cuentas señuelo; no mapean rutas.", ["Las alertas de honeytoken se disparan cuando se usan cuentas señuelo; no mapean rutas hacia cuentas sensibles.", "Las etiquetas de entidad marcan cuentas o dispositivos como sensibles, pero no muestran cómo podría llegar a ellos un atacante.", null, "El estado de los sensores informa sobre los sensores de Defender for Identity, no sobre rutas de ataque."]],
  "sa48": ["Durante un ataque de ransomware operado por humanos, Defender XDR contuvo por sí solo, en minutos, una cuenta de usuario comprometida y varios dispositivos. ¿Qué capacidad lo hizo?", ["Una regla de automatización de Sentinel al crearse el incidente", "Una regla de detección personalizada", "Attack simulation training", "Interrupción automática de ataques (automatic attack disruption)"], "La interrupción automática de ataques usa señales XDR de alta confianza para contener automáticamente usuarios y dispositivos comprometidos. Las detecciones personalizadas generan alertas; no contienen nada por sí solas.", ["Las reglas de automatización de Sentinel actúan sobre los incidentes que configures; no son la capacidad XDR integrada que contuvo este ataque.", "Las reglas de detección personalizadas generan alertas a partir de tus consultas y pueden ejecutar acciones configuradas, pero no ofrecieron esta contención integrada basada en señales.", "Attack simulation training ejecuta simulaciones de phishing para usuarios; no contiene ataques reales.", null]],
  "sa49": ["El SOC confirmó que se robaron las credenciales de un usuario y quiere que las políticas de riesgo de Entra ID Protection traten al usuario como de alto riesgo. ¿Qué acción debe tomar?", ["Descartar el riesgo del usuario (Dismiss user risk)", "Agregar al usuario a un watchlist", "Confirmar que el usuario está comprometido (Confirm user compromised)", "Desactivar UEBA para el usuario"], "'Confirm user compromised' establece el riesgo del usuario en alto, lo que activa el Conditional Access basado en riesgo y ayuda a entrenar las detecciones. Descartar el riesgo hace lo contrario.", ["Descartar el riesgo del usuario lo establece en ninguno, lo contrario de lo que quiere el SOC.", "Los watchlists son datos de referencia de Sentinel y no afectan los niveles de riesgo de Entra ID Protection.", null, "Desactivar UEBA elimina los insights de comportamiento en Sentinel y no eleva el riesgo del usuario en Entra."]],
  "sa50": ["Una investigación descubre que un atacante creó una regla de bandeja de entrada que reenvía el correo de un gerente a una dirección externa. Además de restablecer la contraseña, ¿qué debe hacer el responsable de respuesta?", ["Solo activar MFA, ya que la regla expira por sí sola", "Dejar la regla para que el atacante no se entere", "Eliminar el buzón y restaurarlo desde una copia de seguridad", "Eliminar la regla y revocar las sesiones del usuario"], "Las reglas de bandeja de entrada persisten después de restablecer la contraseña, y las sesiones existentes pueden seguir siendo válidas. Eliminar la regla y revocar los tokens de actualización quitan ambos accesos del atacante.", ["Activar MFA no elimina la regla, y las reglas de bandeja de entrada no expiran; el correo seguiría reenviándose.", "Dejar la regla sigue filtrando el correo del gerente al atacante.", "Eliminar y restaurar el buzón es disruptivo e innecesario cuando la regla maliciosa simplemente se puede eliminar.", null]],
  "sa51": ["Un usuario reporta decenas de solicitudes push de MFA durante la noche que él no inició. ¿Qué debe hacer PRIMERO el analista?", ["Decirle al usuario que apruebe una solicitud para detener las notificaciones", "Restablecer la contraseña y revocar las sesiones, ya que probablemente la contraseña es conocida", "Desactivar MFA para el usuario hasta que paren las solicitudes", "Esperar a que Identity Protection eleve el nivel de riesgo"], "Las solicitudes repetidas indican que alguien ya tiene la contraseña y está intentando un ataque de fatiga de MFA. Restablecerla y revocar las sesiones lo detiene. Aprobar una solicitud le daría acceso al atacante.", ["Aprobar una solicitud completaría el inicio de sesión del atacante y le daría acceso a la cuenta.", null, "Desactivar MFA elimina la última barrera que protege una cuenta cuya contraseña ya es conocida.", "Esperar deja la cuenta expuesta mientras el atacante sigue intentando; el reporte del usuario es suficiente para actuar."]],
  "sa52": ["Defender for Cloud Apps marca una aplicación OAuth recién autorizada con permisos de lectura y escritura de correo que está enviando volúmenes inusuales de email. ¿Cuál es el MEJOR paso de contención?", ["Prohibir (ban) o revocar la aplicación para que su consentimiento y sus tokens dejen de funcionar", "Restablecer las contraseñas de los usuarios que dieron el consentimiento", "Agregar el publicador de la aplicación a un watchlist", "Aumentar el umbral de la política de anomalías"], "Las aplicaciones OAuth usan sus propios tokens, así que restablecer una contraseña no elimina su acceso. Prohibir o revocar la aplicación sí lo elimina. Cambiar umbrales solo oculta alertas.", [null, "Las aplicaciones OAuth conservan sus propios tokens y consentimiento, así que restablecer contraseñas no elimina el acceso de la aplicación.", "Una entrada del publicador en un watchlist solo ayuda a las consultas; no impide que la aplicación envíe correos.", "Subir el umbral oculta la alerta sin detener la aplicación maliciosa."]],
  "sa53": ["El SOC quiere hacer triage de las alertas de DLP de Microsoft Purview en el mismo lugar que las alertas de endpoints e identidad. ¿Dónde pueden hacerlo los analistas?", ["Los registros de inicio de sesión del centro de administración de Entra", "El Azure Activity log", "El informe de cumplimiento de dispositivos de Intune", "La cola de incidentes del portal de Defender"], "Las alertas de DLP de Purview se integran con los incidentes de Defender XDR, así que pueden correlacionarse con otras señales en una sola cola. Los registros de inicio de sesión no contienen alertas de DLP.", ["Los registros de inicio de sesión de Entra muestran eventos de autenticación, no alertas de DLP de Purview.", "El Azure Activity log registra operaciones de administración de recursos de Azure, no coincidencias de políticas DLP.", "Los informes de cumplimiento de Intune muestran el estado de cumplimiento de los dispositivos, no alertas ni incidentes de DLP.", null]],
  "sa54": ["En una alerta de seguridad de Defender for Cloud por un proceso sospechoso en una VM de Azure, ¿qué parte enumera los pasos de mitigación y permite desencadenar una Logic App o crear una regla de supresión?", ["La pestaña Take action", "La hoja Recommendations", "El panel Regulatory compliance", "La hoja Inventory"], "La pestaña Take action de la alerta tiene guía de mitigación, recomendaciones relacionadas, respuestas automatizadas y opciones de supresión. Recommendations cubre la postura, no una alerta específica.", [null, "La página Recommendations cubre hallazgos de postura en todos los recursos, no acciones de respuesta para esta alerta específica.", "El panel Regulatory compliance mapea controles a estándares; no tiene opciones de mitigación ni automatización por alerta.", "Inventory lista los recursos y su cobertura; no contiene acciones de respuesta a alertas."]],
  "sa55": ["En Sentinel, el analista quiere expandir visualmente las entidades de un incidente para encontrar alertas, hosts y cuentas relacionados. ¿Qué herramienta es la adecuada?", ["La página de estado de los conectores de datos", "El gráfico de investigación (investigation graph)", "El workbook de uso del workspace", "El asistente de reglas de análisis"], "El gráfico de investigación parte de las entidades de un incidente y permite expandir las alertas y entidades relacionadas. Un workbook muestra gráficos preparados, no pivoteo interactivo entre entidades.", ["La página de conectores de datos muestra el estado y la configuración de los conectores, no las relaciones entre las entidades del incidente.", null, "El workbook de uso muestra gráficos del volumen de ingesta, no un gráfico interactivo de las entidades del incidente.", "El asistente de reglas de análisis sirve para crear o editar reglas de detección, no para investigar incidentes."]],
  "sa56": ["Un analista quiere saber si la actividad de una cuenta es inusual en comparación con su patrón normal y con sus pares. ¿Dónde debe buscar en Sentinel?", ["La página de la solución en el Content hub", "La página de cobertura de MITRE ATT&CK", "La página de entidad de la cuenta con insights de UEBA", "La página de SOC optimization"], "Las páginas de entidad muestran líneas de tiempo, alertas relacionadas y anomalías de UEBA con comparaciones con pares. La cobertura de MITRE muestra la cobertura de reglas, no el comportamiento del usuario.", ["Las páginas de soluciones del Content hub describen contenido instalable, no el comportamiento de una cuenta.", "La página MITRE ATT&CK muestra la cobertura de detección por técnica, no el comportamiento del usuario.", null, "SOC optimization recomienda mejoras de ingesta y cobertura; no tiene análisis de comportamiento por cuenta."]],
  "sa57": ["Un incidente fue causado por una prueba de penetración aprobada. ¿Cómo debe clasificarse al resolverlo?", ["Falso positivo, porque no ocurrió nada malicioso", "Verdadero positivo por actividad maliciosa, sin más notas", "Actividad esperada (benign positive) con la determinación de prueba de seguridad", "Dejarlo activo hasta que se publique el informe de la prueba"], "La detección fue correcta, pero la actividad estaba autorizada, así que es un resultado esperado/benign positive. Un falso positivo sugeriría que la regla está mal y llevaría al equipo a ajustar una detección que funciona.", ["Falso positivo significa que la lógica de detección estaba mal, pero aquí la regla detectó correctamente una actividad real similar a un ataque.", "Verdadero positivo por actividad maliciosa representa mal una prueba autorizada y distorsiona las métricas.", null, "Dejar el incidente activo satura la cola; se puede resolver ahora con la clasificación y las notas correctas."]],
  "sa58": ["Un analista nuevo en un incidente complejo quiere un resumen en lenguaje sencillo y los próximos pasos recomendados dentro de la página del incidente. ¿Qué debe usar?", ["El workbook de uso del workspace de Sentinel", "Microsoft Security Copilot integrado en el portal de Defender", "Un search job sobre la tabla SecurityIncident", "El historial del Action center"], "Security Copilot integrado crea resúmenes de incidentes y sugerencias de respuesta guiada en la vista del incidente. Un search job recupera datos archivados; no resume nada.", ["El workbook de uso muestra métricas de ingesta y no tiene resúmenes de incidentes ni orientación.", null, "Un search job recupera datos archivados en una tabla; no resume un incidente.", "El historial del Action center lista las acciones de remediación ya tomadas, no un resumen ni los próximos pasos."]],
  "sa59": ["Una alerta contiene un comando de PowerShell largo y ofuscado. El analista quiere una explicación rápida de lo que hace el script. ¿Qué función ayuda MÁS?", ["El análisis de scripts de Security Copilot", "La detección de dispositivos", "Reglas de ajuste de alertas para la alerta de PowerShell", "Secure score"], "El análisis de scripts de Copilot explica scripts y líneas de comandos sospechosos en lenguaje sencillo. El ajuste de alertas suprime alertas; no las explica.", [null, "La detección de dispositivos encuentra dispositivos no administrados en la red y no dice nada sobre el comportamiento de un script.", "El ajuste de alertas suprime o resuelve alertas; no explica el PowerShell.", "El secure score mide la postura; no puede analizar una línea de comandos."]],
  "sa60": ["El analista necesita ver cada evento de proceso, archivo, registro y red en un dispositivo en los minutos antes y después de una alerta. ¿Dónde debe buscar?", ["La lista de vulnerabilidades del dispositivo", "El historial del Secure score", "La página Submissions", "La línea de tiempo del dispositivo (device timeline)"], "La línea de tiempo del dispositivo muestra sus eventos en orden cronológico, con filtros alrededor de la hora de la alerta. Las listas de vulnerabilidades muestran parches faltantes, no actividad.", ["La lista de vulnerabilidades muestra parches faltantes y CVE, no actividad de procesos, archivos o red.", "El historial del secure score muestra cambios de postura en el tiempo, no eventos del dispositivo.", "La página Submissions sirve para enviar correos, archivos y URL a Microsoft para su análisis, no para ver la actividad de un dispositivo.", null]],
  "sa61": ["Una investigación automatizada está esperando aprobación para poner un archivo en cuarentena. ¿Dónde lo aprueba el analista?", ["La página Advanced features en la configuración de endpoints", "La pestaña Pending del Action center", "El informe de Threat analytics", "La página Secure score"], "El Action center lista las acciones de remediación pendientes de aprobación (Pending) y las acciones completadas (History). La configuración de Advanced features activa o desactiva capacidades; no aprueba acciones individuales.", ["La configuración de Advanced features activa o desactiva capacidades para el tenant; no lista acciones pendientes de aprobación.", null, "Los informes de Threat analytics describen campañas de amenazas y la exposición; no tienen una cola de aprobación.", "El secure score da seguimiento a mejoras de postura y no puede aprobar acciones de remediación."]],
  "sa62": ["Defender for Identity reporta un posible uso de Golden Ticket. ¿Qué remediación invalida los tickets de Kerberos falsificados?", ["Restablecer las contraseñas de todos los usuarios que iniciaron sesión ese día", "Reiniciar todos los controladores de dominio al mismo tiempo", "Desactivar Kerberos y usar NTLM temporalmente", "Restablecer la contraseña de KRBTGT dos veces, esperando la replicación entre cada restablecimiento"], "Los Golden Tickets se firman con el hash de KRBTGT. Restablecerla dos veces (porque la contraseña anterior también se acepta) invalida los tickets falsificados. Restablecer contraseñas de usuarios no cambia la clave que los firma.", ["Restablecer contraseñas de usuarios no cambia la clave KRBTGT que firma los TGT falsificados, así que los Golden Tickets siguen siendo válidos.", "Reiniciar los controladores de dominio no cambia la clave KRBTGT y causaría una interrupción sin motivo.", "Desactivar Kerberos no es práctico y no invalida el secreto KRBTGT robado.", null]],
  "sa63": ["Cada analista debe seguir la misma lista de verificación de contención dentro de cada incidente de ransomware en Sentinel. ¿Qué lo proporciona?", ["Tareas de incidente agregadas por una regla de automatización", "Un watchlist llamado 'checklist'", "Un bookmark en cada incidente", "Un workbook fijado en el panel compartido del SOC"], "Las reglas de automatización pueden agregar tareas de incidente para que cada analista vea y marque los mismos pasos dentro del incidente. Un workbook está fuera del incidente y no puede registrar lo completado.", [null, "Un watchlist llamado checklist son solo datos de referencia consultables; no aparece como pasos con seguimiento dentro de los incidentes.", "Los bookmarks guardan resultados de consultas de hunting como evidencia; no son una lista de verificación que los analistas completen.", "Un workbook compartido está fuera del incidente y no puede registrar qué pasos se completaron en cada uno."]],
  "sa64": ["Un analista encuentra dos incidentes de Defender XDR que son el mismo ataque sobre el mismo usuario. ¿Qué debe hacer?", ["Mantener ambos abiertos para que cada uno tenga métricas separadas", "Eliminar uno de los incidentes de la cola", "Vincular las alertas en un solo incidente y resolver el otro", "Crear una regla de supresión para las alertas del segundo incidente"], "Mover (vincular) las alertas a un solo incidente mantiene toda la evidencia junta; luego se puede resolver el incidente vacío. Las reglas de supresión ocultarían alertas reales futuras.", ["Mantener duplicados divide la evidencia entre dos incidentes e infla las métricas.", "Los incidentes no se eliminan de la cola; lo correcto es consolidar las alertas y resolver el incidente vacío.", null, "Suprimir las alertas del segundo incidente ocultaría alertas genuinas futuras que coincidan con el mismo patrón."]],
  "sa65": ["Tras confirmar el hash SHA-256 de un binario de ransomware, el SOC quiere impedir que se ejecute en todos los dispositivos incorporados. ¿Qué deben crear?", ["Una regla de ajuste de alertas para el hash", "Un watchlist de Sentinel con el hash", "Un grupo de dispositivos para los dispositivos afectados", "Un indicador de hash de archivo con la acción Block and remediate"], "Los indicadores de archivo con Block and remediate impiden que el archivo se ejecute y lo remedian dondequiera que se encuentre. Un watchlist puede usarse en consultas, pero no bloquea nada.", ["El ajuste de alertas suprime las alertas sobre el archivo, pero no impide que se ejecute.", "Un watchlist puede referenciarse en consultas, pero no aplica nada en los endpoints.", "Un grupo de dispositivos delimita permisos y automatización; no bloquea un hash de archivo.", null]],
  "sa66": ["Una alerta de viaje imposible muestra inicios de sesión desde Londres y Singapur con diez minutos de diferencia. La IP de Singapur es la salida de la VPN de la empresa. ¿Cuál es la MEJOR respuesta?", ["Confirmar que es la salida corporativa, cerrar como benigna y etiquetar el rango como corporativo", "Deshabilitar la cuenta y restablecer la contraseña de inmediato", "Eliminar la política de detección de anomalías", "Agregar Singapur a una lista de países bloqueados"], "Verificar la IP muestra que es actividad esperada; etiquetar los rangos corporativos reduce futuras alertas falsas. Eliminar la política quita una detección útil.", [null, "Deshabilitar la cuenta y restablecer la contraseña afecta a un usuario legítimo cuando la IP es una salida conocida de la VPN corporativa.", "Eliminar la política de anomalías quita una detección útil para todos en lugar de excluir las IP corporativas conocidas.", "Bloquear Singapur bloquearía la propia salida VPN de la empresa y no resuelve la alerta benigna."]],
  "sa67": ["El analista necesita una lista de los archivos de SharePoint que descargó una cuenta comprometida la semana pasada. ¿Qué fuente de datos la proporciona?", ["Los registros de inicio de sesión de Entra ID", "Microsoft Purview Audit (el registro de auditoría unificado)", "La línea de tiempo de Defender for Endpoint del dispositivo del usuario", "Azure Activity log"], "El registro de auditoría unificado registra las acciones sobre archivos de SharePoint y OneDrive, como FileDownloaded. Los registros de inicio de sesión muestran la autenticación, no el acceso a archivos.", ["Los registros de inicio de sesión registran la autenticación en aplicaciones, no qué archivos de SharePoint se descargaron.", null, "La línea de tiempo del dispositivo cubre la actividad de ese único dispositivo y omite descargas desde otros dispositivos o navegadores.", "El Azure Activity log registra operaciones de administración de recursos de Azure, no el acceso a archivos de SharePoint."]],
  "sa68": ["Un analista quiere ejecutar bajo demanda un playbook de enriquecimiento sobre un incidente de Sentinel. ¿Cómo puede hacerlo?", ["Editar la regla de análisis y volver a ejecutarla", "Crear un nuevo conector de datos para el playbook", "Ejecutar el playbook con desencadenador de incidente desde las acciones del incidente", "Restaurar los registros del incidente desde el data lake"], "Los playbooks con desencadenador de incidente se pueden ejecutar manualmente desde la página del incidente. Volver a ejecutar la regla no desencadena el enriquecimiento.", ["Volver a ejecutar la regla de análisis, en el mejor caso, crea alertas nuevas y no ejecuta el playbook de enriquecimiento.", "Los playbooks no son conectores de datos; crear un conector no hace nada para ejecutar una Logic App.", null, "Restaurar registros devuelve datos archivados para consultas; no desencadena un playbook."]],
  "sa69": ["Defender for Cloud Apps muestra a un usuario descargando archivos de SharePoint de forma masiva a las 3 a. m. El analista quiere impedir que la cuenta inicie sesión mientras continúa la investigación. ¿Qué acción de gobernanza es la adecuada?", ["Descartar la alerta y esperar otra", "Crear una nueva política de archivos para descargas futuras", "Suspender al usuario", "Agregar al usuario a un watchlist de cuentas VIP en Sentinel"], "Suspender al usuario bloquea el inicio de sesión (mediante Entra ID para Microsoft 365) de inmediato, lo que detiene la actividad. Una nueva política de archivos solo afecta a archivos coincidentes en el futuro y no detiene a este usuario.", ["Descartar la alerta deja la cuenta activa mientras puede estar exfiltrando datos.", "Una nueva política de archivos aplica a los archivos coincidentes de ahí en adelante y no impide que este usuario inicie sesión.", null, "Una entrada en un watchlist de VIP cambia cómo las consultas tratan al usuario, pero no bloquea el inicio de sesión."]],
  "sa70": ["Un dispositivo se aisló durante un incidente y luego se limpió y se confirmó que es seguro. ¿Qué debe hacer el analista para que el usuario pueda volver a trabajar con normalidad?", ["Liberar el dispositivo del aislamiento en la página del dispositivo", "Retirar el dispositivo y volver a incorporarlo", "Volver a ejecutar la recopilación del paquete de investigación", "Desactivar la protección de red en ese dispositivo"], "Liberar del aislamiento restaura la conectividad de red normal y queda registrado en el Action center. Retirar y volver a incorporar es innecesario y deja un hueco en la supervisión.", [null, "Retirar y volver a incorporar es innecesario y crea un hueco en la supervisión.", "Recopilar otro paquete de investigación reúne datos, pero deja el dispositivo aislado.", "Desactivar la protección de red debilita el dispositivo y no tiene nada que ver con quitar el aislamiento."]],
  "sa71": ["¿Qué filtro KQL devuelve solo los eventos de las últimas 24 horas en una tabla de advanced hunting de Defender?", ["| where Timestamp < ago(1d)", "| where Timestamp > ago(1d)", "| take 1d", "| summarize by ago(1d)"], "ago(1d) es el momento de hace 24 horas, así que Timestamp mayor que eso significa eventos más recientes. Usar < devuelve todo lo que tiene más de un día.", ["Timestamp < ago(1d) devuelve eventos de hace más de 24 horas, lo contrario de lo que se necesita.", null, "take limita la cantidad de filas devueltas y no acepta un intervalo de tiempo como 1d.", "summarize by ago(1d) agrupa por un valor constante y no filtra al último día."]],
  "sa72": ["Un hunter busca la palabra completa 'mimikatz' en ProcessCommandLine a través de miles de millones de filas. ¿Qué operador suele ser el más rápido?", ["contains", "matches regex", "startswith_cs", "has"], "has usa el índice de términos para encontrar términos completos, así que es mucho más rápido que contains, que busca subcadenas. Usa contains solo para coincidencias parciales dentro de una palabra.", ["contains busca subcadenas y no puede usar el índice de términos, así que es más lento en tablas grandes.", "Las expresiones regulares son la forma más costosa de comparar cadenas y deben ser el último recurso.", "startswith_cs solo coincide con el inicio del valor, así que no encontraría mimikatz si aparece más adelante en la línea de comandos.", null]],
  "sa73": ["¿Qué consulta cuenta los inicios de sesión fallidos por usuario?", ["SigninLogs | project count() by UserPrincipalName | where ResultType != \"0\"", "SigninLogs | extend count() | where ResultType == \"0\"", "SigninLogs | where ResultType != \"0\" | take UserPrincipalName", "SigninLogs | where ResultType != \"0\" | summarize count() by UserPrincipalName"], "summarize count() by agrupa las filas y cuenta cada grupo; filtrar primero por ResultType distinto de cero deja solo los fallos. project y take no agregan.", ["project no agrega, y count() by no es válido dentro de project; además, el filtro se aplica después del intento de conteo.", "extend no puede usar count() como agregación, y ResultType == \"0\" selecciona los inicios de sesión exitosos, no los fallidos.", "take devuelve una cantidad de filas y no acepta un nombre de columna ni produce conteos por usuario.", null]],
  "sa74": ["Un hunter quiere conteos de inicios de sesión en intervalos de una hora para detectar picos. ¿Qué expresión va en el summarize?", ["count() by bin(Timestamp, 1h)", "count() by Timestamp", "count() by ago(1h)", "count() by format_datetime(1h)"], "bin() redondea las marcas de tiempo hacia abajo en intervalos de tamaño fijo, así que cada hora se convierte en una fila. Agrupar por el Timestamp sin procesar da una fila por cada marca de tiempo única.", [null, "Agrupar por el Timestamp sin procesar da una fila por cada valor de tiempo único, no intervalos por hora.", "ago(1h) devuelve un único punto en el tiempo, así que agrupar por él no crearía intervalos por hora.", "format_datetime da formato de texto a un valor datetime y no acepta 1h como argumento; no crea intervalos."]],
  "sa75": ["Un hunter quiere agregar detalles de procesos de DeviceProcessEvents a las conexiones de red de DeviceNetworkEvents, haciendo coincidir DeviceId y el ID de proceso. ¿Qué operador lo hace?", ["union", "join", "extend", "distinct"], "join combina columnas de dos tablas según claves coincidentes. union apila filas de tablas sin hacerlas coincidir.", ["union apila filas de varias tablas sin hacerlas coincidir por claves, así que las columnas no se combinarían.", null, "extend agrega columnas calculadas a partir de la misma fila; no puede traer columnas de otra tabla.", "distinct elimina filas duplicadas de un solo conjunto de resultados y no combina tablas."]],
  "sa76": ["Un hunter tiene 20 direcciones IP maliciosas conocidas de un informe de amenazas y quiere reutilizarlas en varias partes de una consulta. ¿Cuál es el enfoque más limpio?", ["Repetir veinte condiciones or separadas en cada cláusula where de la consulta", "Usar project badIPs al inicio de la consulta", "let badIPs = dynamic([...]); y luego where RemoteIP in (badIPs)", "Poner la lista en un comentario encima de la consulta"], "let define un valor con nombre una sola vez; in() comprueba la pertenencia al arreglo dinámico. Repetir condiciones funciona, pero es propenso a errores y difícil de mantener.", ["Veinte condiciones or repetidas funcionan, pero son propensas a errores y hay que editarlas en todas partes cuando cambia la lista.", "project selecciona columnas de una tabla; no puede definir una lista de valores reutilizable.", null, "El motor de consultas ignora los comentarios, así que las IP no se usarían para filtrar."]],
  "sa77": ["¿Cuál es la diferencia entre project y extend en KQL?", ["project agrega filas; extend agrega tablas", "project elige las columnas de salida; extend agrega columnas nuevas a las existentes", "project ordena los resultados; extend los filtra", "Son alias idénticos del mismo operador"], "extend conserva todas las columnas existentes y agrega columnas calculadas, mientras que project devuelve solo las columnas que enumeres (y también puede calcularlas).", ["Ninguno de los dos operadores agrega filas ni tablas; ambos trabajan sobre las columnas del resultado actual.", null, "El orden se hace con order by o sort by, y el filtrado con where, no con project ni extend.", "Se comportan distinto: project descarta las columnas que no enumeras, mientras que extend las conserva todas."]],
  "sa78": ["¿Qué tabla de advanced hunting contiene detalles de entrega como remitente, destinatario, asunto y acción de entrega de cada correo?", ["EmailUrlInfo", "DeviceEvents", "IdentityLogonEvents", "EmailEvents"], "EmailEvents tiene una fila por correo con remitente, destinatario, asunto y detalles de entrega. EmailUrlInfo solo lista las URL encontradas en los correos.", ["EmailUrlInfo lista las URL encontradas en los correos, no el remitente, el destinatario, el asunto y la acción de entrega.", "DeviceEvents contiene eventos diversos de endpoints, como ASR y protección contra exploits, no datos de correo.", "IdentityLogonEvents registra la actividad de autenticación de fuentes de identidad, no la entrega de correo.", null]],
  "sa79": ["Un hunter busca PowerShell codificado lanzado por aplicaciones de Office en los endpoints. ¿Desde qué tabla debe empezar la consulta?", ["DeviceProcessEvents", "DeviceNetworkEvents", "EmailAttachmentInfo", "CloudAppEvents"], "DeviceProcessEvents registra la creación de procesos con líneas de comandos y procesos padre (InitiatingProcessFileName). Los eventos de red tienen conexiones, pero no el detalle completo de la creación de procesos.", [null, "DeviceNetworkEvents registra conexiones de red, no la creación de procesos con líneas de comandos completas.", "EmailAttachmentInfo describe adjuntos de correo, no procesos que se ejecutan en los endpoints.", "CloudAppEvents contiene actividad en aplicaciones y servicios en la nube, no lanzamientos de procesos en endpoints."]],
  "sa80": ["¿Qué tabla de advanced hunting tiene los eventos de autenticación de Active Directory local vistos por Defender for Identity?", ["DeviceLogonEvents", "AADSignInEventsBeta", "IdentityLogonEvents", "EmailEvents"], "IdentityLogonEvents registra la autenticación que ve Defender for Identity en los controladores de dominio (y algunos inicios de sesión en la nube). DeviceLogonEvents proviene de los endpoints, no del tráfico de los DC.", ["DeviceLogonEvents proviene de Defender for Endpoint en los dispositivos, no del tráfico de autenticación visto en los controladores de dominio.", "AADSignInEventsBeta contiene inicios de sesión de Entra ID (en la nube), no autenticación de Active Directory local.", null, "EmailEvents contiene detalles de entrega de correo y no tiene nada que ver con la autenticación de AD."]],
  "sa81": ["Durante un hunt en Sentinel, un analista encuentra filas sospechosas y quiere guardarlas con notas y entidades para agregarlas después a un incidente. ¿Qué debe crear?", ["Un watchlist", "Un workbook", "Una summary rule", "Un bookmark"], "Los bookmarks conservan resultados de consultas con notas, etiquetas y mapeo de entidades, y se pueden adjuntar a incidentes o usar para crearlos. Un watchlist contiene datos de referencia, no evidencia.", ["Un watchlist contiene datos de referencia como listas de VIP, no evidencia con notas de un hunt.", "Un workbook visualiza resultados de consultas, pero no guarda filas específicas con notas y entidades para incidentes.", "Una summary rule escribe agregaciones programadas en una tabla; no guarda hallazgos específicos como evidencia.", null]],
  "sa82": ["Un hunter quiere recibir una notificación en cuanto nuevos eventos coincidan con una consulta de hunting durante una investigación activa, sin crear una regla de análisis. ¿Qué función es la adecuada?", ["Livestream", "Un search job", "Una operación de restauración", "Content hub"], "Livestream ejecuta una consulta de hunting de forma continua sobre datos nuevos y te notifica las coincidencias. Los search jobs revisan datos almacenados en lugar de vigilar eventos nuevos.", [null, "Un search job recorre datos almacenados a largo plazo de forma asíncrona; no vigila los eventos nuevos a medida que llegan.", "Restaurar devuelve datos archivados para consultarlos y no te notifica nuevas coincidencias.", "Content hub instala soluciones y contenido; no ejecuta consultas sobre datos nuevos."]],
  "sa83": ["Un nuevo IOC debe verificarse contra registros de firewall de hace 18 meses que solo están en retención a largo plazo. ¿Qué función está diseñada para esto?", ["Livestream", "Un search job", "Una regla de análisis NRT", "Un workbook"], "Los search jobs recorren datos a largo plazo de forma asíncrona y escriben las coincidencias en una tabla nueva que puedes consultar. Livestream y las reglas NRT solo miran los datos recién llegados.", ["Livestream solo vigila los datos recién llegados, así que no puede ver registros de hace 18 meses.", null, "Las reglas NRT se ejecutan cada minuto sobre los datos recién ingeridos y no pueden recorrer la retención a largo plazo.", "Los workbooks ejecutan consultas interactivas sobre el nivel de análisis y no están diseñados para recorrer la retención a largo plazo."]],
  "sa84": ["Un hunter quiere una consulta KQL diaria sobre datos del data lake cuyos resultados se escriban en una tabla del nivel de análisis para que las usen las detecciones. ¿Qué debe crear?", ["Una sesión de livestream sobre las tablas del data lake", "Una regla de automatización", "Un KQL job en el data lake de Sentinel", "Un watchlist"], "Los KQL jobs del data lake ejecutan consultas (una vez o según un horario) sobre el lake y pueden promover los resultados al nivel de análisis. Las reglas de automatización actúan sobre incidentes, no sobre datos.", ["Livestream vigila de forma interactiva los datos nuevos del nivel de análisis; no ejecuta jobs programados sobre tablas del data lake ni escribe resultados en una tabla.", "Las reglas de automatización actúan sobre incidentes y alertas, no sobre consultas programadas de datos.", null, "Un watchlist son datos de referencia estáticos y no puede ejecutar una consulta diaria."]],
  "sa85": ["El equipo quiere usar Python, MSTICPy y machine learning para analizar los datos de Sentinel más allá de lo que KQL puede hacer por sí solo. ¿Qué deben usar?", ["Workbooks con visualizaciones KQL", "Watchlists", "Notebooks de Sentinel (Jupyter)", "Reglas de automatización"], "Los notebooks ejecutan Jupyter con bibliotecas como MSTICPy para enriquecimiento, visualización y ML sobre los datos de Sentinel. Los workbooks solo muestran resultados de KQL.", ["Los workbooks visualizan resultados de KQL, pero no pueden ejecutar código de Python, MSTICPy ni machine learning.", "Los watchlists son listas de datos de referencia y no ejecutan ningún análisis.", null, "Las reglas de automatización manejan incidentes (asignar, etiquetar, ejecutar playbooks), no análisis de ciencia de datos."]],
  "sa86": ["El SOC quiere informes de analistas sobre una campaña activa de ransomware, indicando cuáles de sus propios dispositivos están expuestos y qué mitigaciones faltan. ¿Dónde está esto?", ["Threat analytics en Defender XDR", "La página de cobertura MITRE ATT&CK en Sentinel", "El Content hub", "El Action center"], "Los informes de Threat analytics combinan la investigación de amenazas de Microsoft con la exposición, las alertas y el estado de mitigación de tu tenant. La cobertura de MITRE solo muestra qué técnicas cubren tus reglas.", [null, "La página MITRE ATT&CK muestra qué técnicas cubren tus reglas, no informes de campañas con tu exposición y las mitigaciones faltantes.", "Content hub instala soluciones y detecciones; no publica análisis de campañas vinculados a tus dispositivos.", "El Action center lista acciones de remediación, no informes de amenazas ni detalles de exposición."]],
  "sa87": ["Un hunter quiere una sola consulta que encuentre conexiones a una IP maliciosa en los registros de firewalls de tres fabricantes, sin escribir tres consultas separadas. ¿Qué debe usar?", ["Un union de tres tablas en bruto con nombres de columna diferentes", "Un workspace separado para cada fabricante", "Tres reglas casi en tiempo real, una por fabricante", "Parsers ASIM como _Im_NetworkSession"], "ASIM normaliza distintas fuentes en esquemas compartidos, así que una consulta con el parser cubre a todos los fabricantes. Un union en bruto sigue necesitando el mapeo de campos de cada fabricante.", ["Un union en bruto sigue necesitando los nombres de campo específicos de cada tabla, así que en la práctica son tres consultas pegadas.", "Los workspaces separados hacen más difícil, no más fácil, consultar entre fabricantes.", "Tres reglas NRT son tres detecciones separadas, no una sola consulta de hunting entre fabricantes.", null]],
  "sa88": ["Un analista nuevo en KQL quiere describir un hunt en inglés sencillo y obtener una consulta de advanced hunting inicial. ¿Qué puede ayudar?", ["El generador de consultas del Action center", "Security Copilot generando KQL en advanced hunting", "La herramienta de consultas del Secure score", "Una recomendación de Defender for Cloud"], "Security Copilot en advanced hunting puede convertir solicitudes en lenguaje natural en KQL, que el analista debe revisar antes de ejecutar. Las otras opciones no escriben consultas.", ["El Action center lista acciones de remediación y no tiene un generador de consultas.", null, "El secure score mide la postura y no tiene ninguna herramienta que escriba consultas de hunting.", "Las recomendaciones de Defender for Cloud son correcciones de postura, no consultas KQL para hunting."]],
  "sa89": ["Un hunter quiere ver a qué podría llegar una cuenta de servicio comprometida (su radio de impacto) siguiendo las relaciones entre identidades, dispositivos y recursos. ¿Qué capacidad es la adecuada?", ["Una consulta take 100 sobre la tabla SigninLogs para la cuenta", "Un hunting graph construido sobre el Sentinel graph", "Un watchlist de cuentas de servicio", "Una regla de ajuste de alertas para la cuenta"], "El hunting basado en grafos modela las relaciones entre entidades, así que puedes explorar rutas y el radio de impacto desde una entidad inicial. Una consulta plana de inicios de sesión no muestra a qué puede llegar la cuenta.", ["Una consulta plana de los inicios de sesión de la cuenta muestra dónde inició sesión, no a qué recursos le permiten llegar sus relaciones.", null, "Un watchlist de cuentas de servicio es solo una lista de referencia y no muestra relaciones ni alcance.", "Una regla de ajuste de alertas suprime alertas y no dice nada sobre a qué puede acceder la cuenta."]],
  "sa90": ["La columna AdditionalFields contiene JSON y el hunter necesita una propiedad como columna. ¿Qué enfoque de KQL funciona?", ["project AdditionalFields.PropName as text()", "where AdditionalFields has_json PropName", "extend Prop = tostring(parse_json(AdditionalFields).PropName)", "summarize by json(AdditionalFields)"], "parse_json convierte la cadena en un objeto dinámico, lees la propiedad con notación de punto y tostring la convierte en una columna de texto utilizable. Las otras formas no son KQL válido.", ["Esto no es KQL válido: las propiedades dinámicas necesitan parse_json primero, y no existe una función text() que se use así.", "has_json no es un operador de KQL, y una cláusula where filtra filas en lugar de extraer una propiedad como columna.", null, "json() no es una función de KQL, y summarize by agruparía filas en lugar de extraer una propiedad."]],
  "sa91": ["Un hunter quiere marcar los días en que el volumen de datos salientes de un usuario es estadísticamente inusual en comparación con el propio historial de ese usuario. ¿Qué enfoque de KQL es el adecuado?", ["make-series y luego series_decompose_anomalies()", "distinct y luego take 10", "sort by bytes y luego tomar las 10 filas superiores de cada usuario", "union y luego project-away"], "make-series construye una serie de tiempo para cada entidad y series_decompose_anomalies puntúa los valores atípicos frente a la tendencia y la estacionalidad. Ordenar o tomar los valores más altos ignora la línea base de cada usuario.", [null, "distinct y take solo listan algunos valores únicos y no comparan nada con el historial del usuario.", "Ordenar por bytes y tomar las filas superiores encuentra los valores más grandes en general, no los días inusuales respecto de la línea base propia del usuario.", "union combina tablas y project-away descarta columnas; ninguno detecta anomalías estadísticas."]],
  "sa92": ["Una consulta de hunting encontró actividad real de un atacante dos veces. ¿Qué debe hacer el equipo para recibir alertas automáticamente la próxima vez?", ["Guardar los resultados como bookmark y volver a ejecutar la misma consulta a mano cuando haga falta", "Agregar el texto de la consulta a un watchlist", "Exportar los resultados a un archivo CSV cada semana", "Guardar la consulta como detección personalizada o regla de análisis"], "Convertir una consulta de hunting probada en una regla de detección la ejecuta según un horario y genera alertas. Los bookmarks guardan hallazgos pasados, pero no detectan actividad nueva.", ["Los bookmarks conservan hallazgos pasados, y volver a ejecutar una consulta a mano depende de que alguien se acuerde de hacerlo.", "Los watchlists almacenan datos de referencia; poner ahí el texto de una consulta nunca la ejecuta.", "Las exportaciones semanales a CSV son informes manuales de resultados pasados y no generan alertas sobre actividad nueva.", null]],
  "x1": ["El equipo de endpoints quiere que los usuarios vean una notificación cuando se dispare la regla de reducción de la superficie de ataque que impide que las aplicaciones de Office creen procesos hijos, pero que un usuario aún pueda desbloquear la acción por una necesidad real del negocio. ¿Qué modo de regla es el adecuado?", ["Modo auditoría", "Modo advertencia (Warn)", "Modo bloqueo", "No configurado, con una exclusión de carpeta"], "El modo advertencia bloquea la acción, pero muestra un cuadro de diálogo que permite al usuario desbloquearla, lo que da protección con una salida para el negocio. El modo auditoría solo registra eventos y nunca interrumpe ni informa al usuario.", ["El modo auditoría solo registra lo que la regla habría bloqueado; los usuarios no ven nada y no pueden elegir continuar.", null, "El modo bloqueo detiene la acción sin darle al usuario la opción de desbloquearla.", "Dejar la regla sin configurar no da ninguna protección, y una exclusión simplemente omite la verificación."]],
  "x2": ["Las etiquetas y el nombre de un servidor Windows coinciden con las reglas de pertenencia de dos grupos de dispositivos distintos de Defender for Endpoint. ¿A qué grupo pertenecerá el dispositivo?", ["A ambos grupos, aplicando el nivel de automatización más estricto", "Al grupo que se creó primero", "Solo al grupo de mayor rango cuyas reglas cumple", "A ninguno hasta que un administrador lo asigne a mano"], "Un dispositivo se une solo al grupo de dispositivos de mayor rango cuyas reglas cumple, así que el orden de rango decide la pertenencia. Los dispositivos nunca pertenecen a dos grupos a la vez, así que 'ambos grupos' no puede ocurrir.", ["Un dispositivo nunca es miembro de dos grupos de dispositivos a la vez, así que las configuraciones no se combinan.", "La fecha de creación no importa; el orden de rango de los grupos decide la pertenencia.", null, "Los grupos basados en reglas asignan los dispositivos automáticamente; no se necesita asignación manual."]],
  "x3": ["Una empresa quiere administrar los permisos de Defender for Endpoint, Defender for Identity y Defender for Office 365 desde un solo lugar en el portal de Defender usando roles personalizados. ¿Qué deben activar?", ["Microsoft Defender XDR Unified role-based access control", "Asignaciones de roles de Azure RBAC en el grupo de recursos de Sentinel", "El rol Global Reader de Microsoft Entra para cada analista", "Grupos de dispositivos separados para cada carga de trabajo"], "El Unified RBAC de Defender XDR permite a los administradores crear roles personalizados que cubren varias cargas de trabajo de Defender desde una sola página de permisos. Azure RBAC en un grupo de recursos controla recursos de Azure como Sentinel, no los permisos del portal de las cargas de trabajo de Defender.", [null, "Azure RBAC gobierna recursos de Azure como el workspace de Sentinel, no los permisos dentro de Defender for Endpoint, Identity y Office 365.", "Global Reader es un rol de directorio amplio de solo lectura y no puede expresar permisos personalizados de Defender.", "Los grupos de dispositivos delimitan dispositivos de Defender for Endpoint; no cubren permisos de Identity ni de Office 365."]],
  "x4": ["Una empresa mantiene un antivirus de terceros como producto principal, así que Microsoft Defender Antivirus se ejecuta en modo pasivo. Quieren que Defender for Endpoint remedie de todos modos los artefactos maliciosos que detecta su sensor EDR. ¿Qué se debe activar?", ["Protección contra alteraciones", "Acceso controlado a carpetas en modo auditoría", "Protección de red en modo bloqueo", "EDR en modo bloqueo (EDR in block mode)"], "EDR en modo bloqueo permite a Defender for Endpoint bloquear y remediar los artefactos que encuentra el EDR aunque Defender Antivirus esté en modo pasivo. La protección contra alteraciones solo impide que se cambien las configuraciones de seguridad; no agrega remediación.", ["La protección contra alteraciones impide que se cambien configuraciones; no hace que se remedien los hallazgos del EDR.", "El acceso controlado a carpetas protege carpetas, y en modo auditoría solo registra eventos.", "La protección de red bloquea conexiones a destinos maliciosos; no remedia artefactos que encontró el EDR.", null]],
  "x5": ["El SOC quiere impedir que aplicaciones no confiables modifiquen archivos en las carpetas Documentos y Escritorio de los usuarios, un comportamiento común del ransomware, mientras las aplicaciones confiables siguen funcionando. ¿Qué función de Defender for Endpoint es la MEJOR?", ["Acceso controlado a carpetas (controlled folder access)", "La regla ASR 'Use advanced protection against ransomware'", "Un indicador de hash de archivo con acción Block", "Políticas de almacenamiento extraíble de device control"], "El acceso controlado a carpetas protege las carpetas elegidas para que solo las aplicaciones permitidas o confiables puedan modificar sus archivos. La regla ASR contra ransomware inspecciona ejecutables en busca de rasgos de ransomware, pero no protege carpetas específicas contra escrituras de aplicaciones no confiables.", [null, "Esta regla ASR busca rasgos de ransomware en ejecutables; no protege las carpetas elegidas contra escritores no confiables.", "Un indicador de hash bloquea un archivo conocido, no cada aplicación desconocida que intente cifrar documentos.", "Device control gobierna USB y almacenamiento extraíble, no qué aplicaciones pueden escribir en carpetas locales."]],
  "x6": ["Una aplicación web permite a los clientes subir documentos a Azure Blob Storage. El equipo de seguridad quiere que cada blob nuevo se revise en busca de malware poco después de subirse. ¿Qué deben habilitar?", ["Defender for Servers Plan 2 en las VM de la aplicación web", "CSPM fundamental para la suscripción", "Defender for Storage con análisis de malware al subir (on-upload)", "Defender for App Service en la aplicación web que realiza las cargas"], "El análisis de malware de Defender for Storage inspecciona los blobs cuando se suben e informa los resultados. Defender for Servers protege los sistemas operativos de las VM, no los objetos almacenados en una cuenta de almacenamiento.", ["Defender for Servers protege los sistemas operativos de las VM, no los objetos almacenados en Blob Storage.", "El CSPM fundamental da recomendaciones de postura y secure score, no análisis de malware de blobs.", null, "Defender for App Service vigila la plataforma App Service en busca de ataques; no analiza blobs almacenados."]],
  "x7": ["El equipo de seguridad en la nube quiere ver cómo una VM expuesta a internet con una vulnerabilidad conocida podría llevar a un atacante hasta una cuenta de almacenamiento con datos sensibles. ¿Qué opción de Defender for Cloud ofrece este análisis de rutas de ataque?", ["El CSPM fundamental, que está activado por defecto", "El plan Defender CSPM", "Defender for Resource Manager", "El panel Regulatory compliance"], "El análisis de rutas de ataque y el cloud security explorer forman parte del plan de pago Defender CSPM. El CSPM fundamental da el secure score y recomendaciones básicas, pero no análisis de rutas de ataque, lo que lo convierte en la opción tentadora pero incorrecta.", ["El CSPM fundamental es gratuito y da recomendaciones y secure score, pero no análisis de rutas de ataque.", null, "Defender for Resource Manager vigila las operaciones de administración de Azure; no mapea rutas de ataque.", "El panel de cumplimiento normativo mapea controles a estándares; no traza rutas de ataque."]],
  "x8": ["Los administradores quieren que los puertos de administración de las VM de Azure estén cerrados por defecto y se abran solo por solicitud aprobada durante un tiempo limitado. ¿Qué plan de Defender for Cloud incluye el acceso just-in-time a VM?", ["Defender for Servers Plan 1", "CSPM fundamental", "Defender for Resource Manager", "Defender for Servers Plan 2"], "El acceso just-in-time a VM es una función de Defender for Servers Plan 2 que bloquea los puertos de administración y los abre bajo solicitud. El Plan 1 se centra en la integración con Defender for Endpoint y no incluye JIT.", ["El Plan 1 se centra en la integración con Defender for Endpoint y no incluye el acceso just-in-time a VM.", "El CSPM fundamental solo da recomendaciones de postura, no control de puertos JIT.", "Defender for Resource Manager supervisa las operaciones de administración; no bloquea puertos de VM.", null]],
  "x9": ["El equipo de identidad quiere que Defender for Identity detecte solicitudes de certificados sospechosas y otros ataques dirigidos a la autoridad de certificación empresarial de la compañía. ¿Qué deben hacer?", ["Instalar un sensor de Defender for Identity en los servidores AD CS", "Confiar en los sensores que ya están en los controladores de dominio", "Incorporar los servidores de la CA solo a Defender for Endpoint", "Reenviar los registros Security de los servidores de la CA a Sentinel mediante CEF"], "Defender for Identity admite sensores en los servidores AD CS para ver directamente la actividad de los servicios de certificados. Los sensores de los controladores de dominio no ven lo que ocurre dentro del servicio de la autoridad de certificación, así que no bastan.", [null, "Los sensores de los controladores de dominio no ven la actividad dentro de los servicios de certificados en los servidores de la CA.", "Defender for Endpoint protege el endpoint, pero no ofrece las detecciones de AD CS de Defender for Identity.", "Reenviar registros a Sentinel no le da a Defender for Identity los datos que necesita para sus propias detecciones."]],
  "x10": ["Los atacantes siguen enviando malware de día cero en adjuntos de correo que el análisis por firmas no detecta. ¿Qué función de Defender for Office 365 abre los adjuntos en un sandbox antes de que los usuarios puedan acceder a ellos?", ["Política antimalware con filtro de adjuntos comunes", "Safe Links", "Safe Attachments", "Zero-hour auto purge"], "Safe Attachments detona los adjuntos en un sandbox para encontrar malware desconocido antes de la entrega. La política antimalware depende de firmas y filtros de tipo de archivo, así que no detecta el malware nuevo descrito.", ["El filtrado por firmas y tipo de archivo no detecta malware totalmente nuevo, que es el problema descrito.", "Safe Links verifica las URL en el momento del clic; no detona adjuntos.", null, "Zero-hour auto purge actúa después de la entrega cuando cambia un veredicto; no pone primero los adjuntos en un sandbox."]],
  "x11": ["Un auditor necesita ver incidentes, reglas de análisis y workbooks de Sentinel, pero no debe cambiar nada. ¿Qué rol integrado se le debe asignar?", ["Microsoft Sentinel Responder", "Microsoft Sentinel Reader", "Microsoft Sentinel Automation Contributor", "Log Analytics Contributor"], "Microsoft Sentinel Reader da acceso de solo lectura a los datos y recursos de Sentinel. Responder también puede asignar y cerrar incidentes, lo cual es más de lo que necesita un auditor.", ["Responder puede asignar y cerrar incidentes, lo que es más acceso del que debe tener un auditor de solo lectura.", null, "Automation Contributor está pensado para que el servicio de Sentinel ejecute playbooks, no para personas que ven datos.", "Log Analytics Contributor puede cambiar la configuración del workspace, mucho más allá del acceso de solo lectura."]],
  "x12": ["Los servidores Linux deben enviar a Sentinel solo los mensajes de autenticación de nivel warning o superior. ¿Cuál es la forma recomendada de recopilarlos?", ["Instalar el agente heredado de Log Analytics en cada servidor y habilitar todas las facilities de syslog", "Enviar los registros a la Logs Ingestion API desde un cron job", "Dirigir syslog a una cuenta de almacenamiento e importarlo semanalmente", "Usar el Azure Monitor Agent con una DCR que seleccione las facilities de auth y el nivel mínimo"], "El Azure Monitor Agent con una regla de recopilación de datos puede filtrar syslog por facility y severidad mínima, conservando solo lo necesario. El agente heredado de Log Analytics está retirado, y habilitar todas las facilities aumentaría el costo.", ["El agente heredado de Log Analytics está retirado, y recopilar todas las facilities aumenta el costo por datos que nadie necesita.", "La Logs Ingestion API es para aplicaciones personalizadas; construir cron jobs para syslog es frágil e innecesario.", "Una importación semanal no es lo bastante oportuna para la detección y agrega trabajo manual.", null]],
  "x13": ["Un conector trae una tabla en la que una columna grande nunca se usa y algunas filas son ruido de depuración. El SOC quiere descartar ambas cosas antes de que se almacenen los datos. ¿Qué deben usar?", ["Una summary rule del workspace", "Un watchlist de filas a ignorar", "Una transformación en tiempo de ingesta en la regla de recopilación de datos", "Una regla de automatización que elimine las filas no deseadas después de que lleguen"], "Una transformación de DCR ejecuta KQL sobre los datos entrantes, así que puede quitar columnas y filtrar filas antes de que se almacenen y facturen. Una summary rule trabaja sobre datos ya ingeridos, así que no puede reducir lo almacenado.", ["Las summary rules agregan datos después de la ingesta, así que los datos no deseados igual se almacenan y facturan.", "Los watchlists son listas de referencia para consultas; no pueden filtrar datos antes de que se almacenen.", null, "Las reglas de automatización actúan sobre incidentes, no sobre filas de registros, y eliminar después de la llegada no evita el costo de ingesta."]],
  "x14": ["Una regla programada se ejecuta cada 5 minutos y revisa los últimos 5 minutos. Algunos eventos llegan tarde por el retraso de ingesta y nunca se evalúan. ¿Cuál es la solución recomendada?", ["Habilitar la agrupación de alertas para que los eventos tardíos se agreguen a la alerta de la ejecución anterior", "Alargar el período de revisión (lookback) más allá del intervalo de ejecución y filtrar por ingestion_time() para evitar duplicados", "Subir el umbral de alerta de la regla para que se necesiten menos eventos", "Acortar el lookback a 1 minuto para que cada ejecución termine más rápido"], "Hacer el lookback más largo que la frecuencia captura las filas tardías, y filtrar por ingestion_time() evita que las mismas filas generen alertas dos veces. La agrupación de alertas solo agrupa alertas ya creadas; no puede evaluar eventos que la consulta nunca vio.", ["La agrupación de alertas solo combina alertas ya creadas; los eventos que la consulta nunca vio siguen sin producir nada.", null, "Subir el umbral hace que la regla sea menos sensible y no resuelve nada sobre las filas que llegan tarde.", "Un lookback más corto pierde aún más eventos tardíos y empeora el hueco."]],
  "x15": ["El SOC activó una regla de análisis de anomalías integrada, pero no ve incidentes de ella. ¿Dónde aparecen sus resultados?", ["Como incidentes de severidad alta en la cola de incidentes del portal de Defender", "Solo en la tabla SecurityIncident", "En un watchlist con el nombre de la regla", "En la tabla Anomalies, para usarlos en hunting y en otras reglas"], "Las reglas de anomalías escriben registros en la tabla Anomalies en lugar de crear alertas o incidentes, así que los analistas los usan en hunting o en otras detecciones. No crean incidentes, por eso no aparece ninguno en la cola.", ["Las reglas de anomalías no crean incidentes, así que nada llega directamente de ellas a la cola de incidentes.", "SecurityIncident almacena incidentes, y las reglas de anomalías no crean ninguno.", "Los watchlists son listas de referencia que suben las personas; las reglas no escriben resultados en ellos.", null]],
  "x16": ["Una regla de automatización sube la severidad de los incidentes de cierta regla. Una segunda regla de automatización asigna los incidentes de severidad alta a Tier 2. Ambas se desencadenan al crearse el incidente, pero se están perdiendo asignaciones. ¿Qué se debe corregir?", ["Establecer el orden de las reglas para que la regla de severidad se ejecute antes que la de asignación", "Fusionar ambas reglas de automatización en un solo playbook de Logic Apps desencadenado por el incidente", "Cambiar la segunda regla para que se desencadene al crearse la alerta", "Darles a las reglas de automatización el rol Sentinel Contributor"], "Las reglas de automatización se ejecutan según su número de orden, y una regla posterior ve los cambios hechos por las anteriores, así que la regla de severidad debe ejecutarse primero. Mover la lógica a un playbook funcionaría, pero es más pesado y no corrige la causa, que es el orden.", [null, "Un playbook podría hacer ambos pasos, pero es más pesado de construir y ejecutar; la causa real es el orden de las reglas.", "Los desencadenadores de creación de alerta se ejecutan sobre alertas, no sobre el incidente cuya severidad cambió la primera regla.", "El problema es el orden, no los permisos; las reglas de automatización ya actúan sobre los incidentes sin ese rol."]],
  "x17": ["Un analista que revisa una dirección IP dentro de una investigación de Sentinel quiere ejecutar un playbook que consulte solo esa IP. ¿Qué desencadenador debe usar el playbook?", ["Desencadenador de incidente de Microsoft Sentinel", "Desencadenador de alerta de Microsoft Sentinel", "Desencadenador de entidad de Microsoft Sentinel", "Un desencadenador de recurrencia cada 5 minutos"], "El desencadenador de entidad permite a un analista ejecutar un playbook bajo demanda sobre una sola entidad, como una IP. Un desencadenador de incidente pasa todo el incidente, no una entidad elegida.", ["El desencadenador de incidente pasa todo el incidente, no una sola entidad que elija el analista.", "El desencadenador de alerta pasa una alerta, no una entidad elegida de una investigación.", null, "Un desencadenador de recurrencia se ejecuta según un horario, no bajo demanda sobre una IP."]],
  "x18": ["Un playbook usa su identidad administrada para agregar comentarios y cambiar el estado de incidentes de Sentinel. ¿Qué rol debe tener la identidad administrada en el workspace?", ["Microsoft Sentinel Reader", "Microsoft Sentinel Automation Contributor", "Logic App Contributor", "Microsoft Sentinel Responder"], "Responder puede actualizar incidentes, incluidos comentarios y estado, que es exactamente lo que necesita el playbook. Automation Contributor es el rol que se otorga al servicio de Sentinel para que las reglas de automatización ejecuten playbooks; no le da a la identidad del playbook permiso para actualizar incidentes.", ["Reader no puede agregar comentarios ni cambiar el estado de los incidentes.", "Automation Contributor se da al servicio de Sentinel para que las reglas de automatización ejecuten playbooks, no para actualizar incidentes.", "Logic App Contributor administra la propia Logic App; no da derechos sobre los incidentes de Sentinel.", null]],
  "x19": ["Una regla de detección personalizada de Defender XDR encuentra dispositivos que ejecutan un comando conocido de volcado de credenciales. El SOC quiere que cada dispositivo coincidente se aísle automáticamente. ¿Qué deben configurar?", ["Una regla de automatización de Sentinel que cierre el incidente", "La acción automatizada de la regla para aislar el dispositivo", "Una regla de ajuste de alertas para la detección", "Un grupo de dispositivos con nivel de automatización Full"], "Las reglas de detección personalizadas pueden ejecutar acciones de respuesta sobre las entidades que encuentran, como aislar el dispositivo. El nivel de automatización Full gobierna la remediación de las investigaciones automatizadas, no el aislamiento desde una detección personalizada.", ["Cerrar un incidente en Sentinel no aísla ningún dispositivo.", null, "Las reglas de ajuste de alertas ocultan o resuelven alertas; nunca ejecutan acciones de respuesta sobre dispositivos.", "Los niveles de automatización gobiernan la remediación de investigaciones automatizadas, no el aislamiento desencadenado por una detección personalizada."]],
  "x20": ["Una regla de análisis debe excluir las cuentas listadas en un watchlist cuyo alias es ServiceAccounts. ¿Qué función de KQL lee ese watchlist?", ["_GetWatchlist('ServiceAccounts')", "externaldata('ServiceAccounts')", "lookup('ServiceAccounts')", "materialize('ServiceAccounts')"], "_GetWatchlist() con el alias devuelve las filas del watchlist para que una regla pueda hacer join o filtrar contra ellas. externaldata lee archivos desde URL de almacenamiento externo y no conoce los watchlists de Sentinel.", [null, "externaldata lee archivos desde URL de almacenamiento; no tiene relación con los watchlists de Sentinel.", "lookup hace join contra una expresión de tabla; no puede obtener por sí solo un watchlist por su alias.", "materialize guarda en caché el resultado de una subconsulta dentro de una consulta; no lee watchlists."]],
  "x21": ["Una empresa ejecuta servidores Windows en su propio centro de datos y quiere que los cubra Defender for Servers, incluida la integración con Defender for Endpoint, administrados desde Defender for Cloud. ¿Cuál es el enfoque recomendado?", ["Mover los servidores a Azure antes de activar cualquier plan", "Incorporar los servidores solo con un script local y omitir Defender for Cloud", "Conectar los servidores con Azure Arc y habilitar Defender for Servers", "Instalar el sensor de Defender for Identity en cada servidor"], "Azure Arc convierte los servidores locales en recursos de Azure, así que Defender for Servers puede cubrirlos e implementar la integración con Defender for Endpoint. Un script de incorporación local da protección de endpoints, pero no la cobertura del plan de Defender for Cloud que se pide.", ["No es necesario migrar los servidores a Azure; Azure Arc cubre los servidores donde están.", "Un script local da protección de endpoints, pero no la cobertura de Defender for Servers administrada en Defender for Cloud.", null, "El sensor de Defender for Identity va en servidores de identidad como los controladores de dominio, no en todos los servidores."]],
  "x22": ["La empresa usa escritorios VDI no persistentes que se recrean en cada inicio de sesión. Tras incorporarlos con el script local normal, el inventario de dispositivos se llena de entradas duplicadas. ¿Qué se debe usar en su lugar?", ["El script de incorporación VDI para dispositivos no persistentes", "La protección contra alteraciones en la imagen base (golden image)", "Un tenant de Defender for Endpoint separado para VDI", "La detección de dispositivos en modo estándar en el host pool de VDI"], "Microsoft ofrece scripts de incorporación VDI que manejan máquinas no persistentes para que cada escritorio conserve una identidad coherente. La protección contra alteraciones protege configuraciones y no hace nada con los registros de dispositivos duplicados.", [null, "La protección contra alteraciones protege las configuraciones de seguridad y no hace nada con los registros de dispositivos duplicados.", "Usar un tenant separado divide la visibilidad y tampoco maneja las identidades no persistentes.", "La detección de dispositivos encuentra dispositivos no administrados; no cambia cómo se incorporan los escritorios VDI."]],
  "x23": ["Los registros de la UE deben quedarse en una región de la UE y los de EE. UU. en una región de EE. UU., pero un mismo equipo del SOC investiga ambos. ¿Qué diseño de workspaces de Sentinel es el MEJOR?", ["Un solo workspace en EE. UU. que ingiera todos los datos", "Un workspace en cada región con vistas multi-workspace para el SOC", "Un solo workspace en la UE con una regla de exportación de datos que copie ahí los datos de EE. UU.", "Ningún workspace, leyendo los datos solo a través de advanced hunting"], "Los workspaces regionales separados mantienen los datos donde deben residir, y las vistas multi-workspace de incidentes y hunting permiten que un solo SOC trabaje con ambos. Un único workspace en EE. UU. almacenaría datos de la UE fuera de la UE e incumpliría el requisito de residencia.", ["Ingerir los registros de la UE en un workspace de EE. UU. los almacena fuera de la UE e incumple la regla de residencia.", null, "Copiar los datos de EE. UU. al workspace de la UE incumple el requisito de residencia de EE. UU. en la dirección contraria.", "Advanced hunting no reemplaza un workspace de Sentinel para registros de terceros, retención y reglas de análisis."]],
  "x24": ["Los dueños de aplicaciones deben consultar los registros de sus propias VM en el workspace compartido de Log Analytics sin ver los datos de otros equipos ni los incidentes de Sentinel. ¿Qué se debe usar?", ["Asignar a cada dueño Log Analytics Reader en todo el workspace para que filtren", "Crear una instancia de Sentinel separada para cada equipo", "Darle a cada dueño Sentinel Reader en el workspace", "Acceso en contexto de recurso (resource-context) basado en los permisos de los dueños sobre sus VM"], "Con el acceso en contexto de recurso, los usuarios con derechos de lectura sobre sus propios recursos ven solo los datos de registro vinculados a esos recursos. Log Analytics Reader en todo el workspace expondría los datos de todos los equipos.", ["Log Analytics Reader en todo el workspace muestra los registros de todos los equipos, que es justo lo que se debe evitar.", "Instancias de Sentinel separadas por equipo agregan costo y complejidad cuando el acceso en contexto de recurso lo resuelve.", "Sentinel Reader expone los incidentes y todos los datos de Sentinel del workspace, no solo las VM propias de los dueños.", null]],
  "x25": ["Un equipo pequeño quiere aplicar rápidamente a todos los usuarios la configuración recomendada por Microsoft de Safe Links, Safe Attachments y antiphishing, con valores que Microsoft mantiene actualizados. ¿Qué deben usar?", ["Políticas personalizadas copiadas a mano de otro tenant", "Una regla de flujo de correo para cada protección", "Las directivas de seguridad preestablecidas Standard o Strict", "Directivas de alerta en el portal de Defender"], "Las directivas de seguridad preestablecidas aplican en conjunto la configuración de protección recomendada por Microsoft y Microsoft las mantiene actualizadas. Las políticas personalizadas pueden igualarlas, pero hay que crearlas y mantenerlas a mano, lo cual no es rápido.", ["Copiar políticas personalizadas funciona, pero es lento, manual y Microsoft no lo mantiene actualizado.", "Las reglas de flujo de correo no pueden proporcionar la protección de Safe Links ni de Safe Attachments.", null, "Las directivas de alerta generan notificaciones; no establecen la configuración de protección."]],
  "x26": ["Durante live response, un analista quiere ejecutar un script de remediación personalizado de PowerShell en un dispositivo con el comando run. ¿Dónde debe estar primero el script?", ["En la carpeta Descargas local del analista", "Adjunto como comentario en el incidente", "En el paquete de investigación del dispositivo", "En la biblioteca de live response"], "El comando run de live response ejecuta scripts que se hayan subido a la biblioteca de live response. El paquete de investigación se recopila del dispositivo para análisis; no es un lugar para preparar scripts.", ["Live response no puede ejecutar archivos directamente desde la computadora del analista; deben subirse a la biblioteca.", "Los comentarios del incidente son para notas, no para preparar scripts para live response.", "El paquete de investigación son datos recopilados del dispositivo, no un lugar para poner scripts.", null]],
  "x27": ["Una herramienta firmada de línea de negocio se puso en cuarentena en 200 dispositivos como falso positivo. Tras restaurarla, el SOC quiere evitar que se vuelva a marcar con el cambio confiable más acotado. ¿Qué deben hacer?", ["Agregar una exclusión del antivirus para toda la carpeta Program Files", "Crear un indicador Allow para el hash del archivo", "Desactivar la protección en tiempo real en el grupo de dispositivos afectado", "Establecer el nivel de automatización del grupo de dispositivos en None"], "Un indicador Allow para el hash específico del archivo le indica a Defender for Endpoint que confíe en ese archivo exacto. Una exclusión de carpeta también detiene las detecciones, pero es mucho más amplia y deja sin analizar cualquier malware en esa carpeta.", ["Una exclusión de toda la carpeta oculta cualquier malware colocado en ella, lo cual es demasiado amplio.", null, "Desactivar la protección en tiempo real elimina la protección de todo el grupo de dispositivos.", "El nivel de automatización solo cambia la remediación automatizada; el archivo se seguiría detectando y generando alertas."]],
  "x28": ["Una investigación automatizada puso en cuarentena un archivo en muchos dispositivos, y ahora el SOC confirma que estaba limpio. ¿Dónde pueden revertir la remediación?", ["En el historial del Action center, usando deshacer (undo)", "En la línea de tiempo de uno de los dispositivos afectados", "En Threat analytics", "En la página Submissions"], "El historial del Action center lista las acciones de remediación completadas y permite a los analistas deshacerlas. La línea de tiempo del dispositivo muestra eventos de un dispositivo, pero no es donde se revierten las acciones de remediación.", [null, "La línea de tiempo del dispositivo muestra eventos de un dispositivo; las acciones de remediación se deshacen desde el Action center.", "Threat analytics contiene informes sobre amenazas y campañas; no administra acciones de remediación.", "Submissions envía muestras a Microsoft para revisión; no revierte acciones de cuarentena ya ejecutadas."]],
  "x29": ["Se confirmó que la URL de una campaña de phishing es maliciosa. El analista necesita saber qué destinatarios hicieron clic realmente. ¿Qué herramienta de Defender for Office 365 está diseñada para esto?", ["La página de configuración de la política de Safe Links", "Los informes de campañas de Attack simulation training", "Threat Explorer, revisando los clics en URL", "La página de revisión de cuarentena"], "Threat Explorer muestra datos de correo y de clics en URL, así que el analista puede ver quién hizo clic en el enlace malicioso. Los informes de simulación de ataques solo cubren phishing simulado, no una campaña real.", ["La configuración de Safe Links define la protección; no lista quién hizo clic en la URL de una campaña real.", "Los informes de simulación de ataques cubren solo phishing simulado, no una campaña real.", null, "La cuarentena contiene mensajes bloqueados; los mensajes entregados y sus clics no están ahí."]],
  "x30": ["Un boletín legítimo de un socio sigue yendo a correo no deseado por Defender for Office 365. El administrador quiere que Microsoft revise el veredicto. ¿Qué debe hacer?", ["Enviarlo en la página Submissions como que no debió bloquearse", "Crear una política de Safe Links para el dominio del socio", "Eliminar permanentemente los mensajes en Threat Explorer", "Reportarlo como phishing desde el buzón del usuario"], "La página Submissions envía un falso positivo a Microsoft para su análisis y puede agregar una entrada de permitir. Reportarlo como phishing le dice a Microsoft lo contrario de la verdad y reforzaría el bloqueo.", [null, "Safe Links reescribe y verifica URL; no cambia el veredicto de spam del boletín.", "Eliminar permanentemente los mensajes los borra para siempre, lo contrario de lo que quiere el administrador.", "Reportarlo como phishing le dice a Microsoft que el mensaje es malo y refuerza el bloqueo."]],
  "x31": ["Un mensaje se entregó en las bandejas de entrada y una hora después el veredicto de Microsoft cambió a malware. ¿Qué función puede sacar automáticamente las copias entregadas de las bandejas de entrada?", ["La entrega dinámica de Safe Attachments", "Zero-hour auto purge", "La política antispam de salida", "La lista de permitidos/bloqueados del tenant"], "Zero-hour auto purge actúa sobre mensajes ya entregados cuando su veredicto cambia después a spam, phishing o malware. La entrega dinámica retiene los adjuntos durante el análisis antes de la entrega, no después.", ["La entrega dinámica funciona durante el análisis antes de la entrega, no después de un cambio de veredicto posterior.", null, "Las políticas de spam de salida gobiernan el correo enviado fuera del tenant, no los mensajes entrantes entregados.", "La lista de permitidos/bloqueados del tenant afecta el flujo de correo futuro; no mueve copias ya entregadas."]],
  "x32": ["Defender for Identity genera 'Suspected identity theft (pass-the-hash)' para una cuenta. ¿Qué indica esta alerta?", ["La contraseña de la cuenta se adivinó tras muchos inicios de sesión fallidos desde una sola estación de trabajo", "Se presentó un TGT de Kerberos falsificado", "El hash NTLM de la cuenta se usó desde una computadora en la que normalmente no se usa", "Se solicitó un ticket de servicio para una cuenta con SPN"], "Pass-the-hash significa que un atacante reutilizó un hash NTLM robado para autenticarse, lo que Defender for Identity detecta como el uso del hash desde una computadora inusual. Un TGT falsificado es un Golden Ticket, un ataque distinto.", ["Adivinar contraseñas aparece como alertas de fuerza bruta, no de pass-the-hash.", "Un TGT de Kerberos falsificado es un ataque Golden Ticket, que tiene su propia alerta.", null, "Solicitar tickets de servicio para cuentas con SPN es Kerberoasting, otra alerta distinta."]],
  "x33": ["El SOC crea una cuenta señuelo inactiva que nadie debería usar nunca y quiere una alerta cada vez que algo se autentique con ella. ¿Qué deben hacer en Defender for Identity?", ["Etiquetar la cuenta como honeytoken", "Agregar la cuenta a la lista de grupos sensibles", "Deshabilitar la cuenta en Active Directory", "Excluir la cuenta de todas las detecciones"], "Etiquetar una cuenta como honeytoken hace que Defender for Identity alerte sobre cualquier actividad con ella. Marcarla como sensible afecta los informes de rutas de movimiento lateral y el contexto de las alertas, pero no alerta en cada uso.", [null, "Las cuentas sensibles reciben más atención en las rutas de movimiento lateral, pero su uso normal no genera una alerta.", "Deshabilitar la cuenta puede detener el inicio de sesión del atacante, pero Defender for Identity no alertará sobre los intentos como lo haría con un honeytoken.", "Excluir la cuenta de las detecciones es lo contrario de querer alertas sobre ella."]],
  "x34": ["Entra ID Protection marcó un inicio de sesión como riesgoso. El analista lo verificó con el usuario y confirmó que el usuario realmente inició sesión desde un hotel mientras viajaba. ¿Qué debe hacer el analista?", ["Confirmar que el usuario está comprometido", "Bloquear al usuario hasta que regrese", "Restablecer los métodos de MFA del usuario", "Confirmar que el inicio de sesión es seguro (Confirm sign-in safe)"], "Confirmar que el inicio de sesión es seguro marca esa detección específica como falso positivo y alimenta el modelo de riesgo. Confirmar que el usuario está comprometido lo llevaría a riesgo alto, lo contrario de lo que muestran los hechos.", ["Confirmar que el usuario está comprometido eleva el riesgo del usuario a alto, lo cual es incorrecto para un inicio de sesión legítimo.", "Bloquear al usuario castiga a un usuario real por un inicio de sesión confirmado como legítimo.", "Restablecer los métodos de MFA es una respuesta a un compromiso, que aquí no ocurrió.", null]],
  "x35": ["Un atacante robó la contraseña de un usuario e inició sesión. La contraseña se restableció, pero la sesión del navegador del atacante sigue funcionando. ¿Qué debe hacer a continuación el analista?", ["Revocar las sesiones y los tokens de actualización del usuario", "Esperar a que expire la contraseña anterior", "Eliminar y volver a crear la cuenta de usuario", "Agregar la IP del atacante a un watchlist de Sentinel"], "Revocar las sesiones invalida los tokens de actualización y las cookies de sesión, lo que obliga al atacante a iniciar sesión de nuevo con credenciales que ya no tiene. Un watchlist solo ayuda a las detecciones; no termina una sesión activa.", [null, "Esperar no sirve de nada; los tokens de sesión existentes del atacante pueden seguir siendo válidos tras un cambio de contraseña.", "Eliminar la cuenta es destructivo e innecesario cuando las sesiones se pueden revocar.", "Un watchlist alimenta las detecciones, pero no termina la sesión activa del atacante."]],
  "x36": ["Durante una investigación de robo de datos, el SOC quiere bloquear en tiempo real las descargas de archivos sensibles etiquetados desde SharePoint en dispositivos no administrados, mientras los usuarios aún pueden verlos. ¿Qué es lo MEJOR?", ["Una política de archivos de Defender for Cloud Apps con análisis diario", "Suspender a cada usuario que descargó archivos la semana pasada", "Una política de sesión usando Conditional Access app control", "Una directiva de alerta de DLP que envíe un correo al SOC"], "Una política de sesión mediante Conditional Access app control actúa sobre la actividad en tiempo real, por ejemplo bloqueando descargas en dispositivos no administrados. Una política de archivos analiza archivos en reposo y no puede detener una descarga mientras ocurre.", ["Una política de archivos analiza los archivos almacenados según un horario y no puede detener una descarga mientras ocurre.", "Suspender a muchos usuarios es disruptivo y no se enfoca en las descargas en dispositivos no administrados.", null, "Una directiva de alerta solo notifica al SOC; no bloquea nada."]],
  "x37": ["Un atacante accedió a un buzón. El área legal necesita saber qué elementos de correo específicos abrió o sincronizó el atacante. ¿Qué debe buscar el analista en Purview Audit?", ["Registros MailItemsAccessed de ese buzón", "Registros Send del buzón", "Solo los registros de inicio de sesión en el buzón del usuario", "Resultados de message trace de los últimos 10 días"], "Los registros de auditoría MailItemsAccessed muestran qué elementos de correo se leyeron o sincronizaron y desde qué sesión, que es lo que necesita el área legal. Message trace muestra el flujo de correo, no qué mensajes se abrieron.", [null, "Los registros Send muestran los mensajes enviados desde el buzón, no los elementos que abrió el atacante.", "Los registros de inicio de sesión en el buzón muestran que alguien inició sesión, no qué elementos leyó.", "Message trace muestra el flujo de correo que entra y sale del tenant, no qué mensajes se abrieron."]],
  "x38": ["Una VM de pruebas que ejecuta herramientas de seguridad genera todos los días la misma alerta de Defender for Cloud. Los analistas quieren que estas alertas se descarten automáticamente solo para esa VM. ¿Qué deben crear?", ["Una workflow automation que envíe un correo al propietario", "Una regla de supresión de alertas de Defender for Cloud limitada a la VM", "Una exención de Azure Policy para la suscripción que contiene la VM", "Un watchlist de Sentinel con el nombre de la VM"], "Una regla de supresión de alertas en Defender for Cloud descarta automáticamente las alertas coincidentes y puede limitarse a un solo recurso. Una exención de política afecta recomendaciones y cumplimiento, no alertas de seguridad.", ["Enviar un correo al propietario cada día igual deja la alerta abierta para que la atiendan los analistas.", null, "Las exenciones de políticas afectan recomendaciones y cumplimiento, no las alertas de seguridad de Defender for Cloud.", "Un watchlist de Sentinel no cambia cómo Defender for Cloud genera o descarta alertas."]],
  "x39": ["Un analista quiere que un ejecutable sospechoso se detone de forma segura y obtener un informe de comportamiento de su actividad de archivos, registro y red, empezando desde la página del archivo en Defender for Endpoint. ¿Qué acción debe usar?", ["Recopilar paquete de investigación", "Stop and quarantine file", "Agregar un indicador Allow", "Análisis profundo (Deep analysis)"], "El análisis profundo envía el archivo a un sandbox y devuelve un informe de comportamiento detallado. Stop and quarantine contiene el archivo, pero no produce análisis de comportamiento.", ["El paquete de investigación recopila datos del dispositivo como autoruns y registros; no detona un archivo.", "Stop and quarantine contiene el archivo, pero no produce un informe de comportamiento.", "Un indicador Allow confía en el archivo, lo contrario de analizar uno sospechoso.", null]],
  "x40": ["¿Qué tipo de riesgo de Entra ID Protection describe la probabilidad de que una solicitud de autenticación determinada no la haya hecho el propietario de la identidad?", ["Riesgo de usuario", "Riesgo de inicio de sesión", "Riesgo de entidad de servicio", "Riesgo de cumplimiento del dispositivo"], "El riesgo de inicio de sesión puntúa una sola solicitud de autenticación. El riesgo de usuario es la opción tentadora, pero mide la probabilidad de que la identidad en sí esté comprometida, considerando todos sus inicios de sesión.", ["El riesgo de usuario mide la probabilidad de que la identidad en sí esté comprometida, a lo largo de sus inicios de sesión, no una sola solicitud.", null, "El riesgo de entidad de servicio aplica a identidades de carga de trabajo, no a solicitudes de autenticación de usuarios.", "El cumplimiento del dispositivo es un estado de Intune, no un tipo de riesgo de Entra ID Protection."]],
  "x41": ["Un dispositivo se aisló y se eliminó el proceso malicioso. Ahora el analista quiere revisar todo el disco en busca de copias latentes del malware. ¿Qué acción es la adecuada?", ["Análisis rápido de antivirus", "Restringir la ejecución de aplicaciones", "Análisis completo de antivirus", "Liberar del aislamiento"], "Un análisis completo revisa todos los archivos del disco, lo que es necesario para encontrar copias latentes. Un análisis rápido solo revisa las ubicaciones comunes donde suele ejecutarse el malware, así que podría pasarlas por alto.", ["Un análisis rápido revisa las ubicaciones comunes de malware y puede pasar por alto copias latentes en otras partes del disco.", "Restringir la ejecución de aplicaciones limita qué aplicaciones pueden ejecutarse; no busca archivos de malware.", null, "Liberar del aislamiento permite que el dispositivo vuelva a comunicarse con la red antes de revisarlo."]],
  "x42": ["Para un grupo de dispositivos, el SOC quiere que las acciones de remediación de las investigaciones automatizadas se ejecuten sin esperar la aprobación del analista. ¿Qué deben configurar?", ["El nivel de automatización del grupo de dispositivos en Full", "El nivel de automatización del grupo de dispositivos en Semi para todas las carpetas", "La protección contra alteraciones en el grupo de dispositivos", "Una regla de ajuste de alertas para el grupo de dispositivos"], "La automatización Full permite que la investigación automatizada remedie amenazas sin aprobación. Los niveles Semi siguen requiriendo aprobación para algunas o todas las acciones de remediación.", [null, "Los niveles Semi siguen requiriendo aprobación del analista para algunas o todas las acciones de remediación.", "La protección contra alteraciones protege las configuraciones de seguridad; no tiene nada que ver con la aprobación de la remediación.", "Las reglas de ajuste de alertas ocultan o resuelven alertas; no cambian la aprobación de la remediación."]],
  "x43": ["Unos atacantes robaron el certificado de firma de código de un proveedor y están firmando malware con él. El SOC quiere bloquear todo lo firmado con ese certificado en todos los dispositivos incorporados. ¿Qué deben crear?", ["Un indicador de hash de archivo para una muestra conocida", "Un indicador de dominio para el sitio web del proveedor", "Una regla ASR en modo auditoría", "Un indicador de certificado con acción Block"], "Un indicador de certificado bloquea todos los archivos firmados con ese certificado, incluidas muestras aún no vistas. Un solo indicador de hash de archivo solo detiene esa muestra.", ["Un solo indicador de hash bloquea una muestra conocida, no archivos nuevos firmados con el mismo certificado.", "Bloquear el sitio web del proveedor no detiene el malware firmado que ya está en los dispositivos.", "El modo auditoría solo registra; no bloquea nada.", null]],
  "x44": ["Defender for Identity alerta sobre una posible exposición de SPN de Kerberos: un atacante solicitó tickets de servicio para varias cuentas de servicio. ¿Qué remediación reduce MEJOR el impacto?", ["Desactivar Kerberos para el dominio", "Usar gMSA o contraseñas largas y aleatorias para las cuentas de servicio", "Quitar por ahora las cuentas de servicio de todos sus grupos", "Reiniciar los controladores de dominio"], "El Kerberoasting descifra tickets de servicio sin conexión, así que las contraseñas fuertes y administradas, como las gMSA, hacen que el descifrado sea impráctico. Quitar las membresías de grupos puede romper servicios y no impide descifrar los tickets ya obtenidos.", ["Desactivar Kerberos rompería la autenticación en todo el dominio y empujaría a los clientes al NTLM, más débil.", null, "Quitar las membresías de grupos puede romper servicios y no impide el descifrado sin conexión de los tickets ya obtenidos.", "Reiniciar los controladores de dominio no hace nada con los tickets de servicio que el atacante ya tiene."]],
  "x45": ["El área legal exige que las copias de un correo dañino se eliminen de forma que los usuarios no puedan recuperarlas desde Recoverable Items. ¿Qué acción de Threat Explorer se debe usar?", ["Mover a la carpeta de correo no deseado", "Eliminación temporal (soft delete)", "Eliminación permanente (hard delete)", "Mover a elementos eliminados"], "La eliminación permanente purga los mensajes para que los usuarios no puedan restaurarlos. La eliminación temporal los mueve a un lugar desde donde los usuarios aún pueden recuperarlos, lo que incumple el requisito legal.", ["Mover a correo no deseado deja el mensaje en el buzón, donde los usuarios aún pueden abrirlo.", "La eliminación temporal deja los mensajes recuperables por los usuarios, lo que incumple el requisito legal.", null, "El usuario puede abrir y restaurar lo que está en Elementos eliminados."]],
  "x46": ["Tras varias tomas de control de cuentas, el SOC quiere que los usuarios con riesgo de usuario alto se vean obligados a cambiar su contraseña de forma segura en el siguiente inicio de sesión. ¿Qué se debe configurar?", ["Una política de Conditional Access basada en riesgo de usuario que exija un cambio seguro de contraseña", "Una política de anomalías de Defender for Cloud Apps", "Una regla NRT de Sentinel que envíe correos a los usuarios", "Un grupo de Entra para usuarios riesgosos"], "Una política de Conditional Access basada en riesgo puede exigir un cambio seguro de contraseña cuando el riesgo de usuario es alto, lo que además remedia el riesgo. Una regla de Sentinel podría notificar a los usuarios, pero no puede aplicar nada en el inicio de sesión.", [null, "Las políticas de anomalías de Cloud Apps generan alertas; no obligan a cambiar la contraseña en el inicio de sesión.", "Una regla de Sentinel puede enviar correos a los usuarios, pero no puede aplicar nada cuando inician sesión.", "Un grupo por sí solo no hace nada si ninguna política lo usa, y el riesgo cambia demasiado rápido para grupos manuales."]],
  "x47": ["El SOC quiere deshabilitar una cuenta comprometida de Active Directory local directamente desde el portal de Defender usando Defender for Identity. ¿Qué se debe configurar?", ["Un grupo de dispositivos de Defender for Endpoint para los controladores de dominio", "Una cuenta de acción de Defender for Identity con los permisos de AD necesarios", "Password hash sync en Entra Connect", "Un playbook de Sentinel que lea una contraseña de administrador de dominio guardada en Azure Key Vault"], "Defender for Identity usa una cuenta de acción para ejecutar acciones de remediación como deshabilitar usuarios o restablecer contraseñas en AD. Password hash sync afecta el inicio de sesión en la nube y no le da a Defender for Identity derechos para actuar en AD.", ["Los grupos de dispositivos delimitan Defender for Endpoint; no le dan a Defender for Identity derechos para cambiar cuentas de AD.", null, "Password hash sync afecta la autenticación en la nube y no le da a Defender for Identity derechos en AD.", "Guardar una contraseña de administrador de dominio para un playbook es riesgoso y no es la forma en que actúa Defender for Identity."]],
  "x48": ["Un hunter tiene 50 nombres de herramientas sospechosas y quiere encontrar cualquiera de ellos como término completo en cualquier parte de ProcessCommandLine. ¿Qué operador es el MEJOR?", ["in", "has_any", "contains", "=="], "has_any busca términos completos de una lista en cualquier parte de una cadena y usa el índice de términos, así que es rápido. in solo coincide cuando todo el valor de la columna es igual a un elemento de la lista, así que no encuentra líneas de comandos más largas.", ["in solo coincide cuando todo el valor es igual a un elemento de la lista, así que no encuentra líneas de comandos largas.", null, "contains busca subcadenas y no acepta una lista, así que necesitaría 50 condiciones separadas y es más lento.", "== es una comparación de igualdad exacta sobre todo el valor y acepta un solo valor."]],
  "x49": ["Una columna contiene un arreglo dinámico de direcciones IP por fila. El hunter quiere una fila por dirección IP para hacer join con los registros de red. ¿Qué operador se debe usar?", ["project-away", "summarize make_set()", "mv-expand", "top-nested"], "mv-expand convierte cada elemento del arreglo en su propia fila. make_set hace lo contrario: reúne valores en un arreglo.", ["project-away elimina columnas; no divide arreglos en filas.", "make_set reúne valores en un arreglo, lo contrario de lo que se necesita.", null, "top-nested construye agregaciones jerárquicas top-N; no expande arreglos."]],
  "x50": ["Un hunter quiere buscar un hash SHA-256 tanto en DeviceProcessEvents como en DeviceFileEvents en un solo conjunto de resultados. ¿Qué operador combina las filas de las dos tablas?", ["union", "join kind=inner", "lookup", "evaluate bag_unpack"], "union agrega las filas de varias tablas en un solo resultado. join hace coincidir filas por claves, así que solo devolvería filas en las que ambas tablas comparten una clave.", [null, "Un inner join hace coincidir filas por claves y devuelve solo las coincidencias, no todas las filas de ambas tablas.", "lookup enriquece las filas de una tabla de hechos con una tabla de dimensiones; no agrega filas.", "bag_unpack expande una bolsa de propiedades dinámica en columnas; no combina tablas."]],
  "x51": ["Un hunter une eventos de inicio de sesión (izquierda) con eventos de procesos (derecha) por DeviceId con un join simple, y parecen faltar muchas filas de la izquierda que comparten un DeviceId. ¿Qué lo explica?", ["join siempre descarta filas con valores nulos", "El tipo de join predeterminado elimina las claves duplicadas de la izquierda antes de hacer coincidir", "join devuelve solo las primeras 10,000 filas", "La tabla de la derecha debe estar ordenada por tiempo"], "El tipo de join predeterminado es innerunique, que conserva solo una fila de la izquierda por clave antes de hacer coincidir; kind=inner las conserva todas. Los nulos no son el problema aquí, porque las filas tienen valores de DeviceId.", ["join no descarta simplemente las filas con nulos; todas estas filas tienen valores de DeviceId.", null, "No existe un límite fijo de 10,000 filas en los resultados de join que explique las filas faltantes.", "join no necesita que ninguna de las tablas esté ordenada por tiempo."]],
  "x52": ["El hunter quiere los dispositivos incorporados de una lista de inventario que no tuvieron DeviceNetworkEvents en los últimos 7 días. ¿Qué tipo de join devuelve filas del lado izquierdo sin coincidencia en el derecho?", ["inner", "leftouter", "rightsemi", "leftanti"], "leftanti devuelve las filas de la izquierda sin coincidencia a la derecha, que son exactamente los dispositivos sin eventos. leftouter devuelve todas las filas de la izquierda, con y sin coincidencias, así que el hunter igual tendría que filtrar.", ["inner devuelve solo las filas que coinciden en ambos lados, lo contrario de lo que se necesita.", "leftouter devuelve todas las filas de la izquierda, coincidan o no, así que se necesitaría filtrado adicional.", "rightsemi devuelve filas del lado derecho que tienen coincidencia, no filas de la izquierda sin ella.", null]],
  "x53": ["El hunter necesita el registro de inicio de sesión más reciente por dispositivo, con todas sus columnas. ¿Qué expresión KQL es la MEJOR?", ["summarize max(Timestamp) by DeviceId", "take 1 by DeviceId", "summarize arg_max(Timestamp, *) by DeviceId", "distinct DeviceId, Timestamp"], "arg_max(Timestamp, *) devuelve la fila completa con la marca de tiempo más reciente de cada dispositivo. max(Timestamp) devuelve solo el valor de tiempo y pierde las demás columnas.", ["max(Timestamp) devuelve solo el valor de tiempo y pierde el resto de las columnas de la fila.", "take no admite una cláusula by; solo devuelve una cantidad de filas arbitrarias.", null, "distinct devuelve cada par único de dispositivo y hora, no solo el más reciente por dispositivo."]],
  "x54": ["¿Qué tabla de advanced hunting registra los cambios en Active Directory vistos por Defender for Identity, como cambios de membresía de grupos y restablecimientos de contraseña?", ["IdentityLogonEvents", "IdentityDirectoryEvents", "IdentityInfo", "DeviceEvents"], "IdentityDirectoryEvents contiene cambios del directorio, como cambios de membresía de grupos y de contraseñas. IdentityLogonEvents cubre la actividad de autenticación, no cambios en objetos del directorio.", ["IdentityLogonEvents registra la actividad de autenticación, no cambios en objetos del directorio.", null, "IdentityInfo contiene detalles de las cuentas, como departamento y cargo, no eventos de cambio.", "DeviceEvents contiene eventos diversos de endpoints, no cambios de Active Directory vistos por Defender for Identity."]],
  "x55": ["El hunter necesita todas las alertas, de cualquier producto de Defender, en las que intervino un hash SHA-256 específico, con el título y la severidad de cada alerta. ¿Cuál es el MEJOR enfoque?", ["Consultar solo DeviceFileEvents", "Consultar solo EmailAttachmentInfo", "Buscar en la tabla SecurityEvent", "Filtrar AlertEvidence por el hash y hacer join con AlertInfo por AlertId"], "AlertEvidence lista las entidades vinculadas a las alertas y AlertInfo contiene los títulos y la severidad, unidas por AlertId. DeviceFileEvents muestra la actividad de archivos en los dispositivos, pero no si se generaron alertas.", ["DeviceFileEvents muestra la actividad de archivos en los dispositivos, pero no qué alertas involucraron el hash.", "EmailAttachmentInfo cubre solo los adjuntos de correo, no las alertas de todos los productos.", "SecurityEvent contiene eventos de seguridad de Windows en Sentinel, no la evidencia de alertas de Defender.", null]],
  "x56": ["Un hunter necesita los destinatarios de todos los correos entregados que contenían una URL del dominio bad-example.test. ¿Qué enfoque es el adecuado?", ["Consultar EmailUrlInfo por el dominio y hacer join con EmailEvents por NetworkMessageId", "Consultar solo UrlClickEvents", "Consultar DeviceNetworkEvents por el dominio", "Consultar solo EmailEvents usando la columna Subject"], "EmailUrlInfo contiene las URL encontradas en el correo, y hacer join con EmailEvents por NetworkMessageId agrega los destinatarios y los detalles de entrega. UrlClickEvents solo muestra clics, así que omite a los destinatarios que nunca hicieron clic.", [null, "UrlClickEvents registra solo clics, así que se omitirían los destinatarios que nunca hicieron clic.", "DeviceNetworkEvents muestra conexiones de dispositivos, no destinatarios de correo.", "El texto del asunto no revela las URL de un mensaje, así que EmailEvents por sí sola no puede responder esto."]],
  "x57": ["Un hunter quiere encontrar usuarios que eliminaron grandes cantidades de archivos en SharePoint Online y OneDrive en poco tiempo. ¿Qué tabla de advanced hunting es el MEJOR punto de partida?", ["DeviceFileEvents", "EmailEvents", "CloudAppEvents", "IdentityQueryEvents"], "CloudAppEvents contiene la actividad de aplicaciones en la nube, incluidas las operaciones de archivos de SharePoint y OneDrive. DeviceFileEvents cubre archivos en endpoints incorporados, no en servicios en la nube.", ["DeviceFileEvents cubre archivos en endpoints incorporados, no operaciones de SharePoint ni OneDrive.", "EmailEvents cubre la entrega de correo, no eliminaciones de archivos.", null, "IdentityQueryEvents contiene consultas contra Active Directory, no actividad de archivos en la nube."]],
  "x58": ["Un líder de threat hunting quiere ejecutar un hunt basado en hipótesis en Sentinel, manteniendo juntos sus consultas, bookmarks, estado y hallazgos. ¿Qué función es la adecuada?", ["Hunts en el hunting de Sentinel", "Un workbook con consultas fijadas", "Un watchlist", "Una regla de automatización"], "Hunts permite a un equipo administrar un hunt de principio a fin, registrando la hipótesis, las consultas, los bookmarks y el resultado en un solo lugar. Un workbook visualiza datos, pero no registra el progreso de un hunt.", [null, "Un workbook visualiza datos, pero no registra la hipótesis, el estado y los hallazgos de un hunt.", "Un watchlist es una lista de referencia para consultas, no una forma de administrar un hunt.", "Las reglas de automatización actúan sobre incidentes; no organizan el trabajo de hunting."]],
  "x59": ["El hunter necesita KQL completo, incluidos joins entre tablas, sobre una ventana específica de dos días de datos que solo están en retención a largo plazo. ¿Qué debe usar?", ["Un search job sobre la tabla archivada", "Livestream", "Un bookmark", "Restaurar (restore) ese rango de tiempo"], "Restore trae los datos de largo plazo elegidos a uso interactivo, para que el KQL completo funcione sobre ellos. Un search job es la opción tentadora, pero recorre una sola tabla con una consulta limitada y escribe los resultados en una tabla nueva.", ["Un search job recorre una sola tabla con una consulta limitada, así que no es posible usar KQL completo con joins.", "Livestream vigila los eventos nuevos en tiempo real, no datos antiguos en retención a largo plazo.", "Un bookmark guarda filas del resultado de una consulta; no devuelve datos archivados.", null]],
  "x60": ["Los indicadores de inteligencia de amenazas ya están en Sentinel. El SOC quiere alertas cuando un registro de firewall en CommonSecurityLog contenga una IP maliciosa conocida. ¿Cuál es la forma más rápida?", ["Exportar los indicadores a un watchlist cada día", "Habilitar una regla de análisis integrada TI map para IP y CommonSecurityLog", "Crear un bookmark de hunting para cada indicador", "Ejecutar manualmente un search job cada semana"], "Las plantillas de reglas integradas TI map comparan los indicadores con tablas de registros comunes y generan alertas automáticamente. Una exportación diaria a un watchlist duplica datos que Sentinel ya tiene y aun así necesita una regla.", ["Una exportación diaria a un watchlist copia datos que Sentinel ya tiene y aun así necesita una regla para alertar.", null, "Los bookmarks guardan resultados de hunting; no comparan indicadores automáticamente.", "Una búsqueda manual semanal es lenta y no es una alerta."]]
});
